import { randomBytes, randomUUID, scryptSync, timingSafeEqual } from "node:crypto";
import { cookies } from "next/headers";
import { db } from "./db";

const SESSION_DURATION_MS = 30 * 24 * 60 * 60 * 1000; // 30 days
const COOKIE_NAME = "session";

// ─── Password hashing ────────────────────────────────────────────────────────

export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString("hex");
  const hash = scryptSync(password, salt, 64).toString("hex");
  return `${salt}:${hash}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(":");
  if (!salt || !hash) return false;
  const hashBuf = Buffer.from(hash, "hex");
  const candidateBuf = scryptSync(password, salt, 64);
  return timingSafeEqual(hashBuf, candidateBuf);
}

// ─── Session management ──────────────────────────────────────────────────────

export async function createSession(userId: string): Promise<string> {
  const token = randomUUID();
  const expiresAt = new Date(Date.now() + SESSION_DURATION_MS);

  await db.session.create({
    data: { id: token, userId, expiresAt },
  });

  const store = await cookies();
  store.set(COOKIE_NAME, token, {
    httpOnly: true,
    sameSite: "lax",
    path: "/",
    expires: expiresAt,
  });

  return token;
}

export async function destroySession(): Promise<void> {
  const store = await cookies();
  const token = store.get(COOKIE_NAME)?.value;
  if (token) {
    await db.session.deleteMany({ where: { id: token } });
    store.delete(COOKIE_NAME);
  }
}

type SessionUser = {
  id: string;
  email: string;
  name: string | null;
};

export async function getCurrentUser(): Promise<SessionUser | null> {
  const store = await cookies();
  const token = store.get(COOKIE_NAME)?.value;
  if (!token) return null;

  const session = await db.session.findUnique({
    where: { id: token },
    select: { expiresAt: true, user: { select: { id: true, email: true, name: true } } },
  });

  if (!session || session.expiresAt < new Date()) {
    if (session) {
      await db.session.deleteMany({ where: { id: token } });
    }
    return null;
  }

  return session.user;
}

export async function requireUser(): Promise<SessionUser> {
  const user = await getCurrentUser();
  if (!user) {
    throw new HttpError(401, "Authentication required");
  }
  return user;
}

// ─── HTTP error class ────────────────────────────────────────────────────────

export class HttpError extends Error {
  constructor(
    public status: number,
    message: string,
  ) {
    super(message);
  }
}

import { NextResponse } from "next/server";
import { HttpError } from "./auth";

export type ApiResponse<T = unknown> = {
  data?: T;
  error?: string;
  details?: string[];
};

export function json<T>(data: T, init?: ResponseInit): NextResponse<ApiResponse<T>> {
  return NextResponse.json({ data }, init);
}

export function error(status: number, message: string, details?: string[]): NextResponse<ApiResponse> {
  return NextResponse.json({ error: message, details }, { status });
}

export function created<T>(data: T): NextResponse<ApiResponse<T>> {
  return json(data, { status: 201 });
}

export function noContent(): NextResponse {
  return new NextResponse(null, { status: 204 });
}

export function notFound(resource?: string): NextResponse<ApiResponse> {
  return error(404, resource ? `${resource} not found` : "Not found");
}

export function badRequest(message: string, details?: string[]): NextResponse<ApiResponse> {
  return error(400, message, details);
}

export function unauthorized(message = "Authentication required"): NextResponse<ApiResponse> {
  return error(401, message);
}

export function forbidden(message = "Forbidden"): NextResponse<ApiResponse> {
  return error(403, message);
}

// ─── Route handler wrapper ───────────────────────────────────────────────────

type RouteHandler = (
  request: Request,
  context?: Record<string, unknown>,
) => Promise<Response>;

export function handle(handler: RouteHandler): RouteHandler {
  return async (request, context) => {
    try {
      return await handler(request, context);
    } catch (e) {
      if (e instanceof HttpError) {
        return error(e.status, e.message);
      }
      console.error("[API Error]", e);
      return error(500, "Internal server error");
    }
  };
}

import { db } from "./db";

// ─── Types ───────────────────────────────────────────────────────────────────

export type SkillStatus = "LOCKED" | "AVAILABLE" | "IN_PROGRESS" | "COMPLETED" | "MASTERED";

export type SkillNode = {
  slug: string;
  name: string;
  difficulty: number | null;
  prerequisites: string[];
};

export type SkillStatusResult = {
  slug: string;
  name: string;
  status: SkillStatus;
  mastery: number;
  missingPrerequisites: string[];
  selfDeclared: boolean;
};

// ─── Status computation ──────────────────────────────────────────────────────

export function computeSkillStatus(
  skill: SkillNode,
  userSkillMap: Map<string, { status: string; mastery: number; selfDeclared: boolean }>,
): SkillStatusResult {
  const userSkill = userSkillMap.get(skill.slug);

  // Check which prerequisites are met
  const missingPrerequisites = skill.prerequisites.filter((prereqSlug) => {
    const prereq = userSkillMap.get(prereqSlug);
    if (!prereq) return true;
    if (prereq.selfDeclared) return false;
    return prereq.status !== "COMPLETED" && prereq.status !== "MASTERED";
  });

  // If any non-self-declared prerequisite is missing → LOCKED
  if (missingPrerequisites.length > 0) {
    return {
      slug: skill.slug,
      name: skill.name,
      status: "LOCKED",
      mastery: 0,
      missingPrerequisites,
      selfDeclared: userSkill?.selfDeclared ?? false,
    };
  }

  // If user has no record → AVAILABLE
  if (!userSkill) {
    return {
      slug: skill.slug,
      name: skill.name,
      status: "AVAILABLE",
      mastery: 0,
      missingPrerequisites: [],
      selfDeclared: false,
    };
  }

  // Determine status from mastery
  let status: SkillStatus;
  if (userSkill.mastery >= 90) {
    status = "MASTERED";
  } else if (userSkill.mastery >= 80) {
    status = "COMPLETED";
  } else if (userSkill.mastery > 0) {
    status = "IN_PROGRESS";
  } else if (userSkill.status === "COMPLETED" || userSkill.status === "MASTERED") {
    status = userSkill.status as SkillStatus;
  } else {
    status = "AVAILABLE";
  }

  return {
    slug: skill.slug,
    name: skill.name,
    status,
    mastery: userSkill.mastery,
    missingPrerequisites: [],
    selfDeclared: userSkill.selfDeclared,
  };
}

// ─── Path progress ───────────────────────────────────────────────────────────

export type PathProgress = {
  totalSteps: number;
  completedSteps: number;
  percentage: number;
  currentPhase: string | null;
  currentSkill: SkillStatusResult | null;
  nextTask: { skillSlug: string; skillName: string; resourceUrl: string | null } | null;
  statuses: SkillStatusResult[];
};

export async function getPathProgress(
  userId: string,
  pathSlug: string,
): Promise<PathProgress> {
  const path = await db.learningPath.findUnique({
    where: { slug: pathSlug },
    include: {
      steps: {
        include: {
          skill: {
            include: {
              resources: { include: { resource: true } },
              prerequisites: { select: { prerequisite: { select: { slug: true } } } },
            },
          },
        },
        orderBy: { order: "asc" },
      },
    },
  });

  if (!path) {
    throw new Error(`Path not found: ${pathSlug}`);
  }

  // Get all user skills
  const userSkills = await db.userSkill.findMany({
    where: { userId },
    select: { skillId: true, status: true, mastery: true, selfDeclared: true },
  });

  const skillIdToSlug = new Map<string, string>();
  for (const step of path.steps) {
    skillIdToSlug.set(step.skill.id, step.skill.slug);
  }

  const userSkillMap = new Map<string, { status: string; mastery: number; selfDeclared: boolean }>();
  for (const us of userSkills) {
    const slug = skillIdToSlug.get(us.skillId);
    if (slug) {
      userSkillMap.set(slug, { status: us.status, mastery: us.mastery, selfDeclared: us.selfDeclared });
    }
  }

  // Compute statuses
  const statuses: SkillStatusResult[] = path.steps.map((step) => {
    const prereqs = step.skill.prerequisites.map((p) => p.prerequisite.slug);
    return computeSkillStatus(
      { slug: step.skill.slug, name: step.skill.name, difficulty: step.skill.difficulty, prerequisites: prereqs },
      userSkillMap,
    );
  });

  const completedSteps = statuses.filter(
    (s) => s.status === "COMPLETED" || s.status === "MASTERED",
  ).length;
  const totalSteps = statuses.length;

  // Find current phase and skill
  let currentPhase: string | null = null;
  let currentSkill: SkillStatusResult | null = null;
  for (const status of statuses) {
    if (status.status === "IN_PROGRESS") {
      currentSkill = status;
      break;
    }
  }
  if (!currentSkill) {
    for (const status of statuses) {
      if (status.status === "AVAILABLE") {
        currentSkill = status;
        break;
      }
    }
  }
  if (currentSkill) {
    const step = path.steps.find((s) => s.skill.slug === currentSkill!.slug);
    if (step) currentPhase = step.phase;
  }

  // Find next task (first available skill's primary resource)
  let nextTask: PathProgress["nextTask"] = null;
  for (const status of statuses) {
    if (status.status === "AVAILABLE" || status.status === "IN_PROGRESS") {
      const step = path.steps.find((s) => s.skill.slug === status.slug);
      if (step) {
        const primaryResource = step.skill.resources.find((r) => r.isPrimary)?.resource;
        nextTask = {
          skillSlug: status.slug,
          skillName: status.name,
          resourceUrl: primaryResource?.url ?? null,
        };
      }
      break;
    }
  }

  return {
    totalSteps,
    completedSteps,
    percentage: totalSteps > 0 ? Math.round((completedSteps / totalSteps) * 100) : 0,
    currentPhase,
    currentSkill,
    nextTask,
    statuses,
  };
}

// ─── Mastery recomputation ───────────────────────────────────────────────────

export async function recomputeSkillMastery(
  userId: string,
  skillId: string,
): Promise<{ mastery: number; status: string }> {
  // Get resource progress for this skill
  const resourceSkills = await db.resourceSkill.findMany({
    where: { skillId },
    include: {
      resource: {
        include: {
          progress: { where: { userId }, select: { percent: true, status: true } },
        },
      },
    },
  });

  if (resourceSkills.length === 0) {
    return { mastery: 0, status: "AVAILABLE" };
  }

  // Weighted average: courses 40%, others avg 60%
  let totalWeight = 0;
  let weightedSum = 0;

  for (const rs of resourceSkills) {
    const progress = rs.resource.progress[0];
    if (!progress) continue;

    const weight = rs.resource.type === "COURSE" ? 0.4 : 0.6 / Math.max(1, resourceSkills.length - 1);
    totalWeight += weight;
    weightedSum += progress.percent * weight;
  }

  const mastery = totalWeight > 0 ? Math.round((weightedSum / totalWeight) * 100) : 0;

  // Determine status
  let status: string;
  if (mastery >= 90) {
    // Check if any assessment passed
    const passedAssessment = await db.assessmentAttempt.findFirst({
      where: { userId, assessment: { skillId }, passed: true },
    });
    status = passedAssessment ? "MASTERED" : "COMPLETED";
  } else if (mastery >= 80) {
    status = "COMPLETED";
  } else if (mastery > 0) {
    status = "IN_PROGRESS";
  } else {
    status = "AVAILABLE";
  }

  // Upsert user skill
  await db.userSkill.upsert({
    where: { userId_skillId: { userId, skillId } },
    update: { mastery, status },
    create: { userId, skillId, mastery, status },
  });

  return { mastery, status };
}

// ─── Streak computation ──────────────────────────────────────────────────────

export async function computeStreak(userId: string): Promise<number> {
  const activities = await db.dailyActivity.findMany({
    where: { userId },
    select: { date: true },
    orderBy: { date: "desc" },
    take: 100,
  });

  if (activities.length === 0) return 0;

  let streak = 0;
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  for (let i = 0; i < activities.length; i++) {
    const activityDate = new Date(activities[i].date);
    activityDate.setHours(0, 0, 0, 0);

    const expectedDate = new Date(today);
    expectedDate.setDate(expectedDate.getDate() - i);

    if (activityDate.getTime() === expectedDate.getTime()) {
      streak++;
    } else {
      break;
    }
  }

  return streak;
}

import { z } from "zod";
import { db } from "@/lib/db";
