"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";

type User = { id: string; email: string; name: string | null };

export function Nav() {
  const pathname = usePathname();
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/auth/me")
      .then((r) => r.json())
      .then((d) => setUser(d.data))
      .catch(() => setUser(null))
      .finally(() => setLoading(false));
  }, []);

  const handleLogout = async () => {
    await fetch("/api/auth/logout", { method: "POST" });
    setUser(null);
    window.location.href = "/";
  };

  return (
    <header className="sticky top-0 z-50 border-b border-border bg-card/80 backdrop-blur-sm">
      <div className="mx-auto flex h-[var(--nav-height)] max-w-6xl items-center justify-between px-4">
        <div className="flex items-center gap-6">
          <Link href="/" className="font-display text-lg font-semibold text-fg">
            LearnHigh
          </Link>
          <nav className="hidden items-center gap-4 text-sm text-fg-muted sm:flex">
            <Link
              href="/domains"
              className={`transition-colors hover:text-fg ${pathname === "/domains" ? "font-medium text-fg" : ""}`}
            >
              Domains
            </Link>
            <Link
              href="/paths"
              className={`transition-colors hover:text-fg ${pathname === "/paths" ? "font-medium text-fg" : ""}`}
            >
              Learning Paths
            </Link>
            {user && (
              <Link
                href="/dashboard"
                className={`transition-colors hover:text-fg ${pathname === "/dashboard" ? "font-medium text-fg" : ""}`}
              >
                Dashboard
              </Link>
            )}
          </nav>
        </div>

        <div className="flex items-center gap-3">
          {loading ? (
            <div className="h-8 w-20 animate-pulse rounded bg-muted" />
          ) : user ? (
            <div className="flex items-center gap-3">
              <Link
                href="/bookmarks"
                className="text-sm text-fg-muted transition-colors hover:text-fg"
              >
                Bookmarks
              </Link>
              <span className="text-sm text-fg-muted">{user.name ?? user.email}</span>
              <button
                onClick={handleLogout}
                className="rounded-md border border-border px-3 py-1.5 text-sm text-fg-muted transition-colors hover:border-border-strong hover:text-fg"
              >
                Logout
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-2">
              <Link
                href="/login"
                className="rounded-md px-3 py-1.5 text-sm text-fg-muted transition-colors hover:text-fg"
              >
                Log in
              </Link>
              <Link
                href="/register"
                className="rounded-md bg-fg px-3 py-1.5 text-sm font-medium text-card transition-colors hover:bg-fg/90"
              >
                Get started
              </Link>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

"use client";

import Link from "next/link";
import { useState } from "react";
import { useRouter } from "next/navigation";

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();

      if (!res.ok) {
        setError(data.error || "Login failed");
        return;
      }

      router.push("/dashboard");
    } catch {
      setError("Something went wrong");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="mx-auto flex max-w-md flex-col items-center px-4 py-16">
      <h1 className="font-display text-2xl font-bold text-fg">Welcome back</h1>
      <p className="mt-2 text-sm text-fg-muted">Log in to continue your learning journey</p>

      <form onSubmit={handleSubmit} className="mt-8 w-full space-y-4">
        {error && (
          <div className="rounded-md bg-red-50 p-3 text-sm text-red-700">{error}</div>
        )}

        <div>
          <label htmlFor="email" className="block text-sm font-medium text-fg">
            Email
          </label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            className="mt-1 block w-full rounded-md border border-border bg-card px-3 py-2 text-sm text-fg outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
        </div>

        <div>
          <label htmlFor="password" className="block text-sm font-medium text-fg">
            Password
          </label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            className="mt-1 block w-full rounded-md border border-border bg-card px-3 py-2 text-sm text-fg outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full rounded-md bg-fg py-2.5 text-sm font-medium text-card transition-colors hover:bg-fg/90 disabled:opacity-50"
        >
          {loading ? "Logging in..." : "Log in"}
        </button>
      </form>

      <p className="mt-6 text-sm text-fg-muted">
        Don&apos;t have an account?{" "}
        <Link href="/register" className="font-medium text-accent hover:text-accent-dark">
          Sign up
        </Link>
      </p>
    </div>
  );
}

