        <span className="text-fg">{resource.title}</span>
      </div>

      <div className="flex items-start justify-between gap-4">
        <div>
          <span className="text-xs font-medium text-accent">{resource.type}</span>
          <h1 className="mt-1 font-display text-3xl font-bold text-fg">{resource.title}</h1>
          {resource.university && (
            <p className="mt-2 text-lg text-fg-muted">
              {resource.university.name}
              {resource.university.country && ` · ${resource.university.country}`}
            </p>
          )}
        </div>
        {resource.qualityScore && (
          <div className="shrink-0 rounded-lg border border-border bg-card px-4 py-3 text-center">
            <div className="text-2xl font-bold text-success">{Math.round(resource.qualityScore)}</div>
            <div className="text-xs text-fg-faint">quality score</div>
          </div>
        )}
      </div>

      <div className="mt-6 flex flex-wrap items-center gap-4 text-sm text-fg-faint">
        {resource.level && <span>Level: {resource.level}</span>}
        {resource.durationHours && <span>Duration: {resource.durationHours}h</span>}
        {resource.year && <span>Year: {resource.year}</span>}
        {resource.language && <span>Language: {resource.language}</span>}
        {resource.certificate && <span>Certificate available</span>}
      </div>

      {resource.description && (
        <p className="mt-6 leading-relaxed text-fg-muted">{resource.description}</p>
      )}

      <a
        href={resource.url}
        target="_blank"
        rel="noopener noreferrer"
        className="mt-6 inline-flex items-center gap-2 rounded-lg bg-accent px-5 py-2.5 text-sm font-medium text-white transition-colors hover:bg-accent-dark"
      >
        Access resource &rarr;
      </a>

      {/* Quality reasons */}
      {qualityReasons.length > 0 && (
        <section className="mt-8 rounded-lg border border-border bg-card p-6">
          <h2 className="font-display text-lg font-semibold text-fg">Why this resource is recommended</h2>
          <ul className="mt-3 space-y-2">
            {qualityReasons.map((reason: string, i: number) => (
              <li key={i} className="flex items-start gap-2 text-sm text-fg-muted">
                <span className="mt-0.5 text-success">✓</span>
                {reason}
              </li>
            ))}
          </ul>
        </section>
      )}

      {/* Related skills */}
      {resource.skills.length > 0 && (
        <section className="mt-8">
          <h2 className="font-display text-lg font-semibold text-fg">Related Skills</h2>
          <div className="mt-4 flex flex-wrap gap-2">
            {resource.skills.map((rs) => (
              <Link
                key={rs.skill.slug}
                href={`/skills/${rs.skill.slug}`}
                className="rounded-md border border-border px-3 py-1.5 text-sm text-fg-muted transition-colors hover:border-accent hover:text-accent"
              >
                {rs.skill.name}
              </Link>
            ))}
          </div>
        </section>
      )}
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";

export default async function SearchPage({ searchParams }: { searchParams: Promise<{ q?: string }> }) {
  const { q } = await searchParams;
  const query = q?.trim() ?? "";

  let results = {
    domains: [] as Awaited<ReturnType<typeof db.domain.findMany>>,
    paths: [] as Awaited<ReturnType<typeof db.learningPath.findMany>>,
    skills: [] as Awaited<ReturnType<typeof db.skill.findMany>>,
    universities: [] as Awaited<ReturnType<typeof db.university.findMany>>,
    resources: [] as Awaited<ReturnType<typeof db.resource.findMany>>,
  };

  if (query.length >= 2) {
    const pattern = `%${query}%`;
    const [domains, paths, skills, universities, resources] = await Promise.all([
      db.domain.findMany({
        where: { OR: [{ name: { contains: pattern } }, { description: { contains: pattern } }] },
        take: 10,
      }),
      db.learningPath.findMany({
        where: { OR: [{ name: { contains: pattern } }, { tagline: { contains: pattern } }] },
        include: { domain: { select: { name: true } } },
        take: 10,
      }),
      db.skill.findMany({
        where: { OR: [{ name: { contains: pattern } }, { description: { contains: pattern } }] },
        take: 20,
      }),
      db.university.findMany({
        where: { OR: [{ name: { contains: pattern } }] },
        take: 10,
      }),
      db.resource.findMany({
        where: { OR: [{ title: { contains: pattern } }, { description: { contains: pattern } }] },
        include: { university: { select: { name: true } } },
        take: 10,
      }),
    ]);
    results = { domains, paths, skills, universities, resources };
  }

  const totalResults =
    results.domains.length +
    results.paths.length +
    results.skills.length +
    results.universities.length +
    results.resources.length;

  return (
    <div className="mx-auto max-w-4xl px-4 py-12">
      <h1 className="font-display text-3xl font-bold text-fg">Search</h1>

      <form className="mt-6" action="/search" method="get">
        <input
          type="text"
          name="q"
          defaultValue={query}
          placeholder="Search domains, skills, courses..."
          className="w-full rounded-lg border border-border bg-card px-4 py-3 text-fg outline-none focus:border-accent focus:ring-1 focus:ring-accent"
        />
      </form>

      {query.length >= 2 && (
        <p className="mt-4 text-sm text-fg-muted">
          {totalResults} result{totalResults !== 1 ? "s" : ""} for &ldquo;{query}&rdquo;
        </p>
      )}

      {query.length < 2 && (
        <p className="mt-8 text-center text-fg-muted">
          Type at least 2 characters to search.
        </p>
      )}

      {/* Results */}
      {results.domains.length > 0 && (
        <section className="mt-8">
          <h2 className="font-display text-lg font-semibold text-fg">Domains</h2>
          <div className="mt-3 space-y-2">
            {results.domains.map((d) => (
              <Link
                key={d.id}
                href={`/domains/${d.slug}`}
                className="block rounded-lg border border-border bg-card p-4 transition-colors hover:border-accent/40"
              >
                <h3 className="font-medium text-fg">{d.name}</h3>
                <p className="mt-1 text-sm text-fg-muted line-clamp-1">{d.description}</p>
              </Link>
            ))}
          </div>
        </section>
      )}

      {results.paths.length > 0 && (
        <section className="mt-8">
          <h2 className="font-display text-lg font-semibold text-fg">Learning Paths</h2>
          <div className="mt-3 space-y-2">
            {results.paths.map((p) => (
              <Link
                key={p.id}
                href={`/paths/${p.slug}`}
                className="block rounded-lg border border-border bg-card p-4 transition-colors hover:border-accent/40"
              >
                <span className="text-xs font-medium text-accent">{p.domain.name}</span>
                <h3 className="mt-0.5 font-medium text-fg">{p.name}</h3>
                <p className="mt-1 text-sm text-fg-muted">{p.tagline}</p>
              </Link>
            ))}
          </div>
        </section>
      )}

      {results.skills.length > 0 && (
        <section className="mt-8">
          <h2 className="font-display text-lg font-semibold text-fg">Skills</h2>
          <div className="mt-3 space-y-2">
            {results.skills.map((s) => (
              <Link
                key={s.id}
                href={`/skills/${s.slug}`}
                className="block rounded-lg border border-border bg-card p-4 transition-colors hover:border-accent/40"
              >
                <h3 className="font-medium text-fg">{s.name}</h3>
                {s.description && (
                  <p className="mt-1 text-sm text-fg-muted line-clamp-1">{s.description}</p>
                )}
              </Link>
            ))}
          </div>
        </section>
      )}

      {results.universities.length > 0 && (
        <section className="mt-8">
          <h2 className="font-display text-lg font-semibold text-fg">Universities</h2>
          <div className="mt-3 space-y-2">
            {results.universities.map((u) => (
              <div key={u.id} className="rounded-lg border border-border bg-card p-4">
                <h3 className="font-medium text-fg">{u.name}</h3>
                <p className="text-sm text-fg-muted">{u.country}</p>
              </div>
            ))}
          </div>
        </section>
      )}

      {results.resources.length > 0 && (
        <section className="mt-8">
          <h2 className="font-display text-lg font-semibold text-fg">Resources</h2>
          <div className="mt-3 space-y-2">
            {results.resources.map((r) => (
              <a
                key={r.id}
                href={r.url}
                target="_blank"
                rel="noopener noreferrer"
                className="block rounded-lg border border-border bg-card p-4 transition-colors hover:border-accent/40"
              >
                <span className="text-xs font-medium text-accent">{r.type}</span>
                <h3 className="mt-0.5 font-medium text-fg">{r.title}</h3>
                {r.university && (
                  <p className="mt-1 text-sm text-fg-muted">{r.university.name}</p>
                )}
              </a>
            ))}
          </div>
        </section>
      )}

      {query.length >= 2 && totalResults === 0 && (
        <div className="mt-12 text-center">
          <p className="text-fg-muted">No results found. Try different keywords.</p>
        </div>
      )}
    </div>
  );
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";

export default async function BookmarksPage() {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const bookmarks = await db.bookmark.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });

  return (
    <div className="mx-auto max-w-4xl px-4 py-12">
      <h1 className="font-display text-3xl font-bold text-fg">Bookmarks</h1>
      <p className="mt-2 text-fg-muted">Your saved items for quick access.</p>

      {bookmarks.length === 0 ? (
        <div className="mt-12 text-center">
          <p className="text-fg-muted">No bookmarks yet.</p>
          <Link href="/domains" className="mt-4 inline-block text-sm text-accent hover:text-accent-dark">
            Browse domains to find something to save
          </Link>
        </div>
      ) : (
        <div className="mt-8 space-y-3">
          {bookmarks.map((b) => {
            const href =
              b.targetType === "SKILL"
                ? `/skills/${b.targetId}`
                : b.targetType === "RESOURCE"
                ? `/resources/${b.targetId}`
                : b.targetType === "LEARNING_PATH"
                ? `/paths/${b.targetId}`
                : "#";

            return (
              <Link
                key={b.id}
                href={href}
                className="flex items-center justify-between rounded-lg border border-border bg-card p-4 transition-colors hover:border-accent/40"
              >
                <div>
                  <span className="text-xs font-medium text-accent">{b.targetType}</span>
                  <h3 className="mt-0.5 font-medium text-fg">{b.targetId}</h3>
                </div>
                <span className="text-xs text-fg-faint">
                  {new Date(b.createdAt).toLocaleDateString()}
                </span>
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

