async function seedAssessments() {
  console.log("📝 Seeding assessments...");

  for (const assessment of assessments) {
    const skill = await prisma.skill.findUnique({
      where: { slug: assessment.skillSlug },
    });

    if (!skill) {
      console.warn(`  ⚠ Skill "${assessment.skillSlug}" not found, skipping assessment`);
      continue;
    }

    // Create or update assessment
    const existing = await prisma.assessment.findFirst({
      where: { skillId: skill.id, type: assessment.type },
    });

    const assm = existing
      ? await prisma.assessment.update({
          where: { id: existing.id },
          data: {
            title: assessment.title,
            description: assessment.description,
            passScore: assessment.passScore,
          },
        })
      : await prisma.assessment.create({
          data: {
            skillId: skill.id,
            type: assessment.type,
            title: assessment.title,
            description: assessment.description,
            passScore: assessment.passScore,
          },
        });

    // Delete existing questions and recreate
    await prisma.question.deleteMany({ where: { assessmentId: assm.id } });

    for (let i = 0; i < assessment.questions.length; i++) {
      const q = assessment.questions[i];
      await prisma.question.create({
        data: {
          assessmentId: assm.id,
          prompt: q.prompt,
          choices: JSON.stringify(q.choices),
          answerIndex: q.answerIndex,
          explanation: q.explanation,
          order: i,
        },
      });
    }

    console.log(`  ✓ ${assessment.title} (${assessment.questions.length} questions)`);
  }

  const count = await prisma.assessment.count();
  const questionCount = await prisma.question.count();
  console.log(`\n📊 Assessments: ${count}, Questions: ${questionCount}`);
}

seedAssessments()
  .then(async () => {
    await prisma.$disconnect();
    console.log("🎉 Assessment seed complete!");
  })
  .catch(async (e) => {
    console.error(e);
    await prisma.$disconnect();
    process.exit(1);
  });

import { db } from "@/lib/db";
import { handle, json, notFound } from "@/lib/http";

export const GET = handle(async (_request: Request, context?: Record<string, unknown>) => {
  const { skillSlug } = await (context!.params as Promise<{ skillSlug: string }>);

  const skill = await db.skill.findUnique({
    where: { slug: skillSlug },
    select: { id: true, name: true },
  });

  if (!skill) return notFound("Skill");

  const assessment = await db.assessment.findFirst({
    where: { skillId: skill.id },
    include: {
      questions: {
        orderBy: { order: "asc" },
        select: {
          id: true,
          prompt: true,
          choices: true,
          order: true,
        },
      },
    },
  });

  if (!assessment) return notFound("Assessment for this skill");

  // Don't send answerIndex to the client
  const questions = assessment.questions.map((q) => ({
    ...q,
    choices: JSON.parse(q.choices) as string[],
  }));

  return json({
    id: assessment.id,
    title: assessment.title,
    description: assessment.description,
    passScore: assessment.passScore,
    skill: skill.name,
    questions,
  });
});

import { z } from "zod";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { handle, badRequest, json, notFound } from "@/lib/http";

const submitSchema = z.object({
  answers: z.array(z.number().min(0).max(3)),
});

export const POST = handle(async (request: Request, context?: Record<string, unknown>) => {
  const { skillSlug } = await (context!.params as Promise<{ skillSlug: string }>);

  const user = await requireUser();

  const body = await request.json();
  const parsed = submitSchema.safeParse(body);
  if (!parsed.success) {
    return badRequest("Invalid input", parsed.error.issues.map((i) => i.message));
  }

  const skill = await db.skill.findUnique({
    where: { slug: skillSlug },
    select: { id: true },
  });
  if (!skill) return notFound("Skill");

  const assessment = await db.assessment.findFirst({
    where: { skillId: skill.id },
    include: { questions: { orderBy: { order: "asc" } } },
  });
  if (!assessment) return notFound("Assessment");

  if (parsed.data.answers.length !== assessment.questions.length) {
    return badRequest(`Expected ${assessment.questions.length} answers, got ${parsed.data.answers.length}`);
  }

  // Grade
  let correct = 0;
  const results = assessment.questions.map((q, i) => {
    const isCorrect = parsed.data.answers[i] === q.answerIndex;
    if (isCorrect) correct++;
    return {
      questionId: q.id,
      prompt: q.prompt,
      choices: JSON.parse(q.choices) as string[],
      selected: parsed.data.answers[i],
      correct: q.answerIndex,
      isCorrect,
      explanation: q.explanation,
    };
  });

  const score = Math.round((correct / assessment.questions.length) * 100);
  const passed = score >= assessment.passScore;

  // Record attempt
  const attempt = await db.assessmentAttempt.create({
    data: {
      userId: user.id,
      assessmentId: assessment.id,
      score,
      passed,
    },
  });

  return json({
    attemptId: attempt.id,
    score,
    passed,
    correct,
    total: assessment.questions.length,
    passScore: assessment.passScore,
    results,
  });
});

"use client";

import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";

type Question = {
  id: string;
  prompt: string;
  choices: string[];
  order: number;
};

type Assessment = {
  id: string;
  title: string;
  description: string;
  passScore: number;
  skill: string;
  questions: Question[];
};

type QuizResult = {
  attemptId: string;
  score: number;
  passed: boolean;
  correct: number;
  total: number;
  passScore: number;
  results: {
    questionId: string;
    prompt: string;
    choices: string[];
    selected: number;
    correct: number;
    isCorrect: boolean;
    explanation: string;
  }[];
};

export default function QuizPage() {
  const params = useParams();
  const skillSlug = params.skillSlug as string;

  const [assessment, setAssessment] = useState<Assessment | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const [currentQ, setCurrentQ] = useState(0);
  const [answers, setAnswers] = useState<(number | null)[]>([]);
  const [submitted, setSubmitted] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState<QuizResult | null>(null);

  useEffect(() => {
    fetch(`/api/assessments/${skillSlug}`)
      .then((r) => {
        if (!r.ok) throw new Error("No assessment found");
        return r.json();
      })
      .then((d) => {
        setAssessment(d.data);
        setAnswers(new Array(d.data.questions.length).fill(null));
      })
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  }, [skillSlug]);

  const handleAnswer = (choiceIndex: number) => {
    const newAnswers = [...answers];
    newAnswers[currentQ] = choiceIndex;
    setAnswers(newAnswers);
  };

  const handleSubmit = async () => {
    if (!assessment) return;
    setSubmitting(true);
    try {
      const res = await fetch(`/api/assessments/${skillSlug}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ answers: answers.map((a) => a ?? 0) }),
      });
      const data = await res.json();
      setResult(data.data);
      setSubmitted(true);
    } catch {
      setError("Failed to submit quiz");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="mx-auto max-w-2xl px-4 py-12">
        <div className="animate-pulse space-y-4">
          <div className="h-8 w-48 rounded bg-muted" />
          <div className="h-4 w-96 rounded bg-muted" />
          <div className="h-64 rounded-lg bg-muted" />
        </div>
      </div>
    );
  }

  if (error || !assessment) {
    return (
      <div className="mx-auto max-w-2xl px-4 py-12 text-center">
        <h1 className="font-display text-2xl font-bold text-fg">No quiz available</h1>
        <p className="mt-2 text-fg-muted">{error || "No assessment found for this skill."}</p>
        <Link href={`/skills/${skillSlug}`} className="mt-4 inline-block text-accent hover:text-accent-dark">
          Back to skill
        </Link>
      </div>
    );
  }

  // Results view
  if (submitted && result) {
    return (
      <div className="mx-auto max-w-2xl px-4 py-12">
        <div className={`rounded-lg border p-6 ${result.passed ? "border-success/30 bg-success-light/30" : "border-red-300 bg-red-50"}`}>
          <h1 className="font-display text-2xl font-bold text-fg">
            {result.passed ? "Quiz Passed!" : "Not quite there yet"}
          </h1>
          <div className="mt-4 flex items-center gap-6">
            <div className="text-4xl font-bold text-accent">{result.score}%</div>
            <div className="text-sm text-fg-muted">
              {result.correct}/{result.total} correct
              <br />
              Pass threshold: {result.passScore}%
            </div>
          </div>
        </div>

        <div className="mt-8 space-y-6">
          <h2 className="font-display text-lg font-semibold text-fg">Review Answers</h2>
          {result.results.map((r, i) => (
            <div
              key={r.questionId}
              className={`rounded-lg border p-4 ${r.isCorrect ? "border-success/30" : "border-red-300"}`}
            >
              <div className="flex items-start gap-3">
                <span className={`mt-0.5 text-lg ${r.isCorrect ? "text-success" : "text-red-500"}`}>
                  {r.isCorrect ? "✓" : "✗"}
                </span>
                <div className="flex-1">
                  <p className="font-medium text-fg">
                    {i + 1}. {r.prompt}
                  </p>
                  <div className="mt-2 space-y-1">
                    {r.choices.map((choice, ci) => (
                      <div
                        key={ci}
                        className={`rounded px-3 py-1.5 text-sm ${
                          ci === r.correct
                            ? "bg-success-light font-medium text-success"
                            : ci === r.selected && !r.isCorrect
                            ? "bg-red-50 text-red-600"
                            : "text-fg-muted"
                        }`}
                      >
                        {choice}
                        {ci === r.correct && " ✓"}
                        {ci === r.selected && !r.isCorrect && " ✗"}
                      </div>
                    ))}
                  </div>
                  <p className="mt-2 text-xs text-fg-faint">{r.explanation}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-8 flex gap-4">
          <Link
            href={`/skills/${skillSlug}`}
            className="rounded-lg border border-border px-4 py-2 text-sm font-medium text-fg hover:border-accent/40"
          >
            Back to skill
          </Link>
          <button
            onClick={() => {
              setSubmitted(false);
              setResult(null);
              setCurrentQ(0);
              setAnswers(new Array(assessment.questions.length).fill(null));
            }}
            className="rounded-lg bg-accent px-4 py-2 text-sm font-medium text-white hover:bg-accent-dark"
          >
            Retake quiz
          </button>
        </div>
      </div>
    );
  }

  // Quiz view
  const question = assessment.questions[currentQ];
  const progress = ((currentQ + 1) / assessment.questions.length) * 100;

  return (
    <div className="mx-auto max-w-2xl px-4 py-12">
      <div className="mb-6">
        <Link href={`/skills/${skillSlug}`} className="text-sm text-fg-muted hover:text-fg">
          &larr; {assessment.skill}
        </Link>
        <h1 className="mt-2 font-display text-2xl font-bold text-fg">{assessment.title}</h1>
      </div>

      {/* Progress bar */}
      <div className="mb-6">
        <div className="flex items-center justify-between text-sm text-fg-muted">
          <span>Question {currentQ + 1} of {assessment.questions.length}</span>
          <span>{Math.round(progress)}%</span>
        </div>
        <div className="progress-bar mt-2">
          <div className="progress-bar-fill bg-accent" style={{ width: `${progress}%` }} />
        </div>
      </div>

      {/* Question */}
      <div className="rounded-lg border border-border bg-card p-6">
        <h2 className="text-lg font-medium text-fg">{question.prompt}</h2>
        <div className="mt-4 space-y-2">
          {question.choices.map((choice, i) => (
            <button
              key={i}
              onClick={() => handleAnswer(i)}
              className={`w-full rounded-lg border p-3 text-left text-sm transition-all ${
                answers[currentQ] === i
                  ? "border-accent bg-accent-light/50 font-medium text-accent-dark"
                  : "border-border hover:border-border-strong"
              }`}
            >
              <span className="mr-2 font-medium text-fg-faint">{String.fromCharCode(65 + i)}.</span>
              {choice}
            </button>
          ))}
        </div>
      </div>

      {/* Navigation */}
      <div className="mt-6 flex items-center justify-between">
        <button
          onClick={() => setCurrentQ((q) => Math.max(0, q - 1))}
          disabled={currentQ === 0}
          className="rounded-lg border border-border px-4 py-2 text-sm font-medium text-fg disabled:opacity-30"
        >
          Previous
        </button>

        {currentQ < assessment.questions.length - 1 ? (
          <button
            onClick={() => setCurrentQ((q) => q + 1)}
            className="rounded-lg bg-fg px-4 py-2 text-sm font-medium text-card hover:bg-fg/90"
          >
            Next
          </button>
        ) : (
          <button
            onClick={handleSubmit}
            disabled={submitting || answers.includes(null)}
            className="rounded-lg bg-accent px-4 py-2 text-sm font-medium text-white hover:bg-accent-dark disabled:opacity-50"
          >
            {submitting ? "Submitting..." : "Submit quiz"}
          </button>
        )}
      </div>
    </div>
  );
}

import { db } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { getPathProgress } from "@/lib/skills";
import { handle, json } from "@/lib/http";

export const GET = handle(async () => {
  const user = await getCurrentUser();
  if (!user) {
    return json({ missions: [], streak: 0 });
  }

  // Get active goal
  const activeGoal = await db.userGoal.findFirst({
    where: { userId: user.id, status: "ACTIVE" },
    include: { path: { select: { slug: true, name: true } } },
  });

  if (!activeGoal) {
    return json({ missions: [], streak: 0 });
  }

  // Get path progress to find next tasks
  const progress = await getPathProgress(user.id, activeGoal.path.slug);

  // Build daily missions from next available skills
  const missions: Array<{
    skillSlug: string;
    skillName: string;
    resourceTitle: string | null;
    resourceUrl: string | null;
    type: string;
    estimatedMinutes: number;
    completed: boolean;
  }> = [];

  // Find next 3 available/in-progress skills and their primary resources
  let count = 0;
  for (const status of progress.statuses) {
    if (count >= 3) break;
    if (status.status === "AVAILABLE" || status.status === "IN_PROGRESS") {
      // Find the skill's primary resource
      const skillResources = await db.resourceSkill.findMany({
        where: {
          skill: { slug: status.slug },
          isPrimary: true,
        },
        include: { resource: { select: { slug: true, title: true, url: true, type: true, durationHours: true } } },
        take: 1,
      });

      const primaryResource = skillResources[0]?.resource;

      // Check if already completed
      let completed = false;
      if (primaryResource) {
        const prog = await db.userProgress.findUnique({
          where: { userId_resourceId: { userId: user.id, resourceId: primaryResource.id } },
          select: { status: true },
        });
        completed = prog?.status === "COMPLETED";
      }

      missions.push({
        skillSlug: status.slug,
        skillName: status.name,
        resourceTitle: primaryResource?.title ?? null,
        resourceUrl: primaryResource?.url ?? null,
        type: primaryResource?.type ?? "RESOURCE",
        estimatedMinutes: primaryResource?.durationHours ? Math.round(primaryResource.durationHours * 60 / 10) : 30,
        completed,
      });
      count++;
    }
  }

  // Check today's activity
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const activity = await db.dailyActivity.findUnique({
    where: { userId_date: { userId: user.id, date: today } },
    select: { actions: true, minutes: true },
  });

  return json({
    missions,
    todayActivity: activity,
    goalName: activeGoal.path.name,
  });
});

"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

type Mission = {
  skillSlug: string;
  skillName: string;
  resourceTitle: string | null;
  resourceUrl: string | null;
  type: string;
  estimatedMinutes: number;
  completed: boolean;
};

type DailyMissionData = {
  missions: Mission[];
  todayActivity: { actions: number; minutes: number } | null;
  goalName: string | null;
};

export function DailyMission() {
  const [data, setData] = useState<DailyMissionData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/daily-mission")
      .then((r) => r.json())
      .then((d) => setData(d.data))
      .catch(() => setData(null))
      .finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="rounded-lg border border-border bg-card p-6">
        <div className="animate-pulse space-y-3">
          <div className="h-5 w-32 rounded bg-muted" />
          <div className="h-4 w-48 rounded bg-muted" />
          <div className="h-16 rounded bg-muted" />
        </div>
      </div>
    );
  }

  if (!data || data.missions.length === 0) return null;

  const completedCount = data.missions.filter((m) => m.completed).length;
  const totalEstimated = data.missions.reduce((sum, m) => sum + m.estimatedMinutes, 0);

  return (
    <div className="rounded-lg border border-accent/30 bg-accent-light/20 p-6">
      <div className="flex items-center justify-between">
        <div>
          <span className="text-xs font-medium text-accent-dark">TODAY&apos;S MISSION</span>
          <h2 className="mt-1 font-display text-lg font-semibold text-fg">{data.goalName}</h2>
        </div>
        {data.todayActivity && (
          <div className="text-right text-sm text-fg-muted">
            <div>{data.todayActivity.actions} actions</div>
            <div>{data.todayActivity.minutes} min today</div>
          </div>
        )}
      </div>

      <div className="mt-4 space-y-2">
        {data.missions.map((mission) => (
          <div
            key={mission.skillSlug}
            className={`flex items-center gap-3 rounded-md p-3 ${
              mission.completed ? "bg-success-light/50" : "bg-card"
            }`}
          >
            <span className={`text-lg ${mission.completed ? "text-success" : "text-fg-faint"}`}>
              {mission.completed ? "✓" : "○"}
            </span>
            <div className="flex-1 min-w-0">
              <Link
                href={`/skills/${mission.skillSlug}`}
                className="text-sm font-medium text-fg hover:text-accent"
              >
                {mission.skillName}
              </Link>
              {mission.resourceTitle && (
                <p className="truncate text-xs text-fg-faint">{mission.resourceTitle}</p>
              )}
            </div>
            <div className="shrink-0 text-right">
              <span className="text-xs text-fg-faint">~{mission.estimatedMinutes}min</span>
              {mission.resourceUrl && !mission.completed && (
                <a
                  href={mission.resourceUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="ml-2 text-xs font-medium text-accent hover:text-accent-dark"
                >
                  Start
                </a>
              )}
            </div>
          </div>
        ))}
      </div>

      <div className="mt-4 flex items-center justify-between text-sm text-fg-muted">
        <span>{completedCount}/{data.missions.length} tasks</span>
        <span>~{totalEstimated} minutes</span>
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

type ContinueData = {
  lastResource: {
    slug: string;
    title: string;
    url: string;
    type: string;
  } | null;
  skillSlug: string | null;
  skillName: string | null;
  progress: number;
  goalName: string | null;
  goalSlug: string | null;
} | null;

export function ContinueLearning() {
