        {data.goalName}
      </h3>
      {data.skillName && (
        <p className="mt-1 text-sm text-fg-muted">{data.skillName}</p>
      )}

      <div className="mt-4 flex items-center gap-4">
        <div className="flex-1">
          <p className="text-sm font-medium text-fg">{data.lastResource.title}</p>
          <p className="text-xs text-fg-faint">{data.lastResource.type}</p>
