      </div>

      <div className="mt-4 flex gap-3">
        {data.lastResource.url && (
          <a
            href={data.lastResource.url}
            target="_blank"
            rel="noopener noreferrer"
            className="rounded-lg bg-accent px-4 py-2 text-sm font-medium text-white hover:bg-accent-dark"
          >
            Resume
          </a>
        )}
        {data.goalSlug && (
