import Link from "next/link";
import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { getPathProgress, computeStreak } from "@/lib/skills";
import { db } from "@/lib/db";
import { ProgressBar } from "@/components/ProgressBar";
import { SkillStatusBadge } from "@/components/SkillStatusBadge";
import { DailyMission } from "@/components/DailyMission";
import { ContinueLearning } from "@/components/ContinueLearning";

export default async function DashboardPage() {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const [activeGoal, streak, recentProgress, allBookmarks] = await Promise.all([
    db.userGoal.findFirst({
      where: { userId: user.id, status: "ACTIVE" },
      include: {
        path: {
          include: {
            domain: { select: { name: true, slug: true } },
          },
        },
      },
    }),
    computeStreak(user.id),
    db.userProgress.findMany({
      where: { userId: user.id },
      include: { resource: { select: { slug: true, title: true, type: true } } },
      orderBy: { lastAccessedAt: "desc" },
      take: 5,
    }),
    db.bookmark.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 5,
    }),
  ]);

  let progress = null;
  if (activeGoal) {
    progress = await getPathProgress(user.id, activeGoal.path.slug);
  }

  return (
    <div className="mx-auto max-w-6xl px-4 py-12">
      <div className="mb-8">
        <h1 className="font-display text-3xl font-bold text-fg">
          Welcome back{user.name ? `, ${user.name}` : ""}
        </h1>
        {streak > 0 && (
          <p className="mt-2 text-fg-muted">
            🔥 {streak} day streak
          </p>
        )}
      </div>

      {/* Daily Mission — prominent */}
      <div className="mb-8">
        <DailyMission />
      </div>

      {/* Active Goal */}
      {activeGoal && progress ? (
        <div className="mb-8 rounded-lg border border-border bg-card p-6">
          <div className="flex items-center justify-between">
            <div>
              <span className="text-xs font-medium text-accent">CURRENT GOAL</span>
              <h2 className="mt-1 font-display text-xl font-semibold text-fg">
                <Link href={`/paths/${activeGoal.path.slug}`} className="hover:text-accent">
                  {activeGoal.path.name}
                </Link>
              </h2>
              <p className="text-sm text-fg-muted">{activeGoal.path.domain.name}</p>
            </div>
            <div className="text-right">
              <div className="text-3xl font-bold text-accent">{progress.percentage}%</div>
              <div className="text-sm text-fg-muted">
                {progress.completedSteps}/{progress.totalSteps}
              </div>
            </div>
          </div>

          <ProgressBar value={progress.percentage} className="mt-4" />

          {/* Current task */}
          {progress.currentSkill && (
            <div className="mt-4 rounded-md bg-muted p-4">
              <div className="flex items-center justify-between">
                <div>
                  <span className="text-xs font-medium text-fg-faint">CURRENT</span>
                  <p className="mt-0.5 font-medium text-fg">{progress.currentSkill.name}</p>
                  <SkillStatusBadge status={progress.currentSkill.status} />
                </div>
                {progress.currentSkill.mastery > 0 && (
                  <span className="text-lg font-bold text-accent">
                    {Math.round(progress.currentSkill.mastery)}%
                  </span>
                )}
              </div>
            </div>
          )}

          {/* Next task */}
          {progress.nextTask && (
            <div className="mt-3 rounded-md border border-accent/20 bg-accent-light/30 p-4">
              <span className="text-xs font-medium text-accent-dark">NEXT UP</span>
              <p className="mt-0.5 font-medium text-fg">{progress.nextTask.skillName}</p>
              <div className="mt-2 flex items-center gap-3">
                {progress.nextTask.resourceUrl && (
                  <a
                    href={progress.nextTask.resourceUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-sm text-accent hover:text-accent-dark"
                  >
                    Start learning &rarr;
                  </a>
                )}
                <Link
                  href={`/quiz/${progress.nextTask.skillSlug}`}
                  className="text-sm text-fg-muted hover:text-fg"
                >
                  Take quiz
                </Link>
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="mb-8 rounded-lg border border-dashed border-border bg-card p-8 text-center">
          <h2 className="font-display text-lg font-semibold text-fg">No active goal yet</h2>
          <p className="mt-2 text-sm text-fg-muted">
            Choose a learning path to start tracking your progress.
          </p>
          <Link
            href="/paths"
            className="mt-4 inline-block rounded-lg bg-accent px-4 py-2 text-sm font-medium text-white hover:bg-accent-dark"
          >
            Browse learning paths
          </Link>
        </div>
      )}

      {/* Continue Learning */}
      <div className="mb-8">
        <ContinueLearning />
      </div>

      <div className="grid gap-8 lg:grid-cols-2">
        {/* Recent activity */}
        <section>
          <h2 className="font-display text-lg font-semibold text-fg">Recent Activity</h2>
          {recentProgress.length === 0 ? (
            <p className="mt-4 text-sm text-fg-muted">No activity yet. Start learning!</p>
          ) : (
            <div className="mt-4 space-y-2">
              {recentProgress.map((p) => (
                <div
                  key={p.id}
                  className="flex items-center justify-between rounded-md border border-border bg-card px-4 py-3"
                >
                  <div>
                    <p className="text-sm font-medium text-fg">{p.resource.title}</p>
                    <p className="text-xs text-fg-faint">{p.resource.type}</p>
                  </div>
                  <div className="text-right">
                    <span className="text-sm font-medium text-accent">{Math.round(p.percent)}%</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>

        {/* Bookmarks */}
        <section>
          <h2 className="font-display text-lg font-semibold text-fg">Bookmarks</h2>
          {allBookmarks.length === 0 ? (
            <p className="mt-4 text-sm text-fg-muted">No bookmarks yet.</p>
          ) : (
            <div className="mt-4 space-y-2">
              {allBookmarks.map((b) => (
                <div
                  key={b.id}
                  className="rounded-md border border-border bg-card px-4 py-3"
                >
                  <p className="text-sm font-medium text-fg">{b.targetId}</p>
                  <p className="text-xs text-fg-faint">{b.targetType}</p>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

