// Official university educational platforms
// Only these platforms are authorized as resource sources

export type Platform = {
  slug: string;
  name: string;
  baseUrl: string;
  universitySlug: string;
  type: "LECTURE_RECORDINGS" | "OPEN_COURSEWARE" | "ONLINE_COURSES" | "COURSE_WEBSITE";
};

export const platforms: Platform[] = [
  // MIT
  {
    slug: "mit-ocw",
    name: "MIT OpenCourseWare",
    baseUrl: "https://ocw.mit.edu",
    universitySlug: "mit",
    type: "OPEN_COURSEWARE",
  },
  // Stanford
  {
    slug: "stanford-online",
    name: "Stanford Online",
    baseUrl: "https://online.stanford.edu",
    universitySlug: "stanford",
    type: "ONLINE_COURSES",
  },
  {
    slug: "stanford-courses",
    name: "Stanford Course Websites",
    baseUrl: "https://cs.stanford.edu/courses",
    universitySlug: "stanford",
    type: "COURSE_WEBSITE",
  },
  // UCSD
  {
    slug: "ucsd-podcast",
    name: "UCSD Podcast (ETS)",
    baseUrl: "https://podcast.ucsd.edu",
    universitySlug: "ucsd",
    type: "LECTURE_RECORDINGS",
  },
  // Berkeley
  {
    slug: "berkeley-webcasts",
    name: "Berkeley Webcasts",
    baseUrl: "https://webcast.berkeley.edu",
    universitySlug: "berkeley",
    type: "LECTURE_RECORDINGS",
  },
  {
    slug: "berkeley-cs",
    name: "Berkeley CS Courses",
    baseUrl: "https://cs61a.org",
    universitySlug: "berkeley",
    type: "COURSE_WEBSITE",
  },
  // Harvard
  {
