import { PrismaClient } from "../../src/generated/prisma/client.js";
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import path from "node:path";
import {
  platforms,
  ucsdCourses,
  mitCourses,
  stanfordCourses,
  harvardCourses,
  yaleCourses,
  type UniversityCourse,
} from "./data/platforms.js";

const dbPath = path.resolve(process.cwd(), "prisma/dev.db");
const adapter = new PrismaBetterSqlite3({ url: `file:${dbPath}` });
const prisma = new PrismaClient({ adapter });

const allCourses = [
  ...ucsdCourses,
  ...mitCourses,
  ...stanfordCourses,
  ...harvardCourses,
  ...yaleCourses,
];

async function seedPlatforms() {
  console.log("🏛️  Seeding university platforms...");

  for (const platform of platforms) {
    await prisma.university.upsert({
      where: { slug: platform.universitySlug },
      update: {},
      create: {
        slug: platform.universitySlug,
        name: platform.universitySlug.toUpperCase(),
        country: "United States",
        website: platform.baseUrl,
      },
    });
  }

  console.log(`  ✓ ${platforms.length} platforms registered`);
}

async function seedUniversityCourses() {
  console.log("\n📚 Seeding university-specific resources...");

  let created = 0;
  let skipped = 0;

  for (const course of allCourses) {
    const platform = platforms.find((p) => p.slug === course.platformSlug);
    if (!platform) {
      console.warn(`  ⚠ Platform "${course.platformSlug}" not found, skipping ${course.code}`);
      skipped++;
      continue;
    }

    const university = await prisma.university.findUnique({
      where: { slug: platform.universitySlug },
    });

    if (!university) {
      console.warn(`  ⚠ University "${platform.universitySlug}" not found, skipping ${course.code}`);
      skipped++;
      continue;
    }

    // Create resource slug from course code and term
    const resourceSlug = `${platform.universitySlug}-${course.code.toLowerCase().replace(/\s+/g, "-")}-${course.term}`;

    // Find skills to link
    const skills = await prisma.skill.findMany({
      where: { slug: { in: course.skillSlugs } },
    });

    if (skills.length === 0) {
      console.warn(`  ⚠ No skills found for ${course.code} (${course.skillSlugs.join(", ")}), skipping`);
      skipped++;
      continue;
    }

    // Create or update resource
    const resource = await prisma.resource.upsert({
      where: { slug: resourceSlug },
      update: {
        title: `${course.code} - ${course.title}`,
        type: "LECTURE",
        url: course.url,
        description: `${course.title} offered at ${university.name} in ${course.term}`,
        instructor: course.instructor,
        language: "en",
        level: "INTERMEDIATE",
        year: course.year,
        universityId: university.id,
        qualityScore: 85 + Math.floor(Math.random() * 15), // 85-99
        qualityMeta: JSON.stringify({
          reasons: [
            `Official ${university.name} course`,
            `Platform: ${platform.name}`,
            `Instructor: ${course.instructor}`,
            `Year: ${course.year}`,
          ],
        }),
        verified: true,
      },
      create: {
        slug: resourceSlug,
        title: `${course.code} - ${course.title}`,
        type: "LECTURE",
        url: course.url,
        description: `${course.title} offered at ${university.name} in ${course.term}`,
        instructor: course.instructor,
        language: "en",
        level: "INTERMEDIATE",
        year: course.year,
        universityId: university.id,
        qualityScore: 85 + Math.floor(Math.random() * 15),
        qualityMeta: JSON.stringify({
          reasons: [
            `Official ${university.name} course`,
            `Platform: ${platform.name}`,
            `Instructor: ${course.instructor}`,
            `Year: ${course.year}`,
          ],
        }),
        verified: true,
      },
    });

    // Link to skills
    for (const skill of skills) {
      await prisma.resourceSkill.upsert({
        where: { resourceId_skillId: { resourceId: resource.id, skillId: skill.id } },
        update: { isPrimary: true },
        create: {
          resourceId: resource.id,
          skillId: skill.id,
          isPrimary: true,
        },
      });
    }

    created++;
    console.log(`  ✓ ${course.code} - ${course.title} (${university.name}, ${course.term})`);
  }

  console.log(`\n📊 University resources: ${created} created, ${skipped} skipped`);
}

async function printStats() {
  const stats = await Promise.all([
    prisma.resource.count({ where: { verified: true } }),
    prisma.resource.count({ where: { verified: false } }),
    prisma.university.count(),
  ]);

  console.log(`\n📊 Final stats:`);
  console.log(`  Verified resources: ${stats[0]}`);
  console.log(`  Unverified resources: ${stats[1]}`);
  console.log(`  Universities: ${stats[2]}`);
}

seedPlatforms()
  .then(() => seedUniversityCourses())
  .then(() => printStats())
  .then(async () => {
    await prisma.$disconnect();
    console.log("\n🎉 University seed complete!");
  })
  .catch(async (e) => {
    console.error(e);
    await prisma.$disconnect();
    process.exit(1);
  });

