/**
 * University Source Discovery Engine — Platform Detector
 *
 * Identifies the type of educational platform from a URL.
 * Handles: OCW, Podcasts, Webcasts, Course Sites, YouTube, Canvas, Kaltura, Custom.
 */

export type PlatformType =
  | "OCW"
  | "PODCAST"
  | "WEBCAST"
  | "COURSE_SITE"
  | "YOUTUBE"
  | "CANVAS"
  | "KALTURA"
  | "CUSTOM";

export type DetectedPlatform = {
  type: PlatformType;
  baseUrl: string;
  departmentUrl?: string;
  catalogUrl?: string;
  confidence: number; // 0-1
  metadata?: Record<string, unknown>;
};

// Pattern → PlatformType mapping
const PLATFORM_PATTERNS: Array<{
  pattern: RegExp;
  type: PlatformType;
  extract?: (url: URL) => Partial<DetectedPlatform>;
}> = [
  // MIT OCW
  {
    pattern: /^https?:\/\/ocw\.mit\.edu/,
    type: "OCW",
    extract: (url) => ({
      catalogUrl: `${url.origin}/courses/`,
    }),
  },
  // Stanford Online
  {
    pattern: /^https?:\/\/online\.stanford\.edu/,
    type: "COURSE_SITE",
  },
  // Stanford course sites
  {
    pattern: /^https?:\/\/cs\d{3}\.stanford\.edu/,
    type: "COURSE_SITE",
  },
  // Berkeley Webcasts
  {
    pattern: /^https?:\/\/webcast\.berkeley\.edu/,
    type: "WEBCAST",
  },
  // Berkeley CS course sites
  {
    pattern: /^https?:\/\/(cs\d{2}[a-z]|eecs)\.berkeley\.edu/,
    type: "COURSE_SITE",
  },
  // Harvard CS50
  {
    pattern: /^https?:\/\/cs50\.harvard\.edu/,
    type: "COURSE_SITE",
  },
  // Yale OYC
  {
    pattern: /^https?:\/\/oyc\.yale\.edu/,
    type: "OCW",
  },
  // CMU course pages
  {
    pattern: /^https?:\/\/www\.cs\.cmu\.edu\/~courses/,
    type: "COURSE_SITE",
  },
  // UCSD Podcast
  {
    pattern: /^https?:\/\/podcast\.ucsd\.edu/,
    type: "PODCAST",
  },
  // Generic university podcast patterns
  {
    pattern: /^https?:\/\/podcast\.[a-z]+\.edu/,
    type: "PODCAST",
  },
  // Generic university webcast patterns
  {
    pattern: /^https?:\/\/webcast\.[a-z]+\.edu/,
    type: "WEBCAST",
  },
  // Canvas LMS
  {
    pattern: /^https?:\/\/[a-z]+\.canvas\.edu/,
    type: "CANVAS",
  },
  {
    pattern: /^https?:\/\/canvas\.instructure\.com/,
    type: "CANVAS",
  },
  // Kaltura
  {
    pattern: /^https?:\/\/[a-z]+\.kaltura\.com/,
    type: "KALTURA",
  },
  // YouTube channels/playlists
  {
    pattern: /^https?:\/\/(www\.)?youtube\.com\/(channel|playlist|c\/|@)/,
    type: "YOUTUBE",
  },
  // Coursera
  {
    pattern: /^https?:\/\/(www\.)?coursera\.org/,
    type: "COURSE_SITE",
  },
  // edX
  {
    pattern: /^https?:\/\/(www\.)?edx\.org/,
    type: "COURSE_SITE",
  },
  // Generic /courses/ path on university domains
  {
    pattern: /^https?:\/\/[a-z]+\.(edu|ac\.uk|ac\.jp)\/courses/,
    type: "COURSE_SITE",
    extract: (url) => ({
      catalogUrl: url.href,
    }),
  },
];

/**
 * Detect platform type from a URL.
 */
export function detectPlatform(url: string): DetectedPlatform | null {
  try {
    const parsed = new URL(url);

    for (const { pattern, type, extract } of PLATFORM_PATTERNS) {
      if (pattern.test(parsed.href)) {
        const base: DetectedPlatform = {
          type,
          baseUrl: `${parsed.origin}`,
          confidence: 0.9,
        };

        if (extract) {
          const extra = extract(parsed);
          return { ...base, ...extra };
        }

        return base;
      }
    }

    // Fallback: check if it's a university domain
    if (/\.edu$|\.ac\.(uk|uk|jp|au)$/.test(parsed.hostname)) {
      return {
        type: "COURSE_SITE",
        baseUrl: `${parsed.origin}`,
        confidence: 0.5,
      };
    }

    return null;
  } catch {
    return null;
  }
}

/**
 * Detect platform from HTML content (for when URL alone isn't enough).
 */
export function detectPlatformFromHtml(
  url: string,
  html: string,
): DetectedPlatform | null {
  const fromUrl = detectPlatform(url);

  // Check for Canvas indicators in HTML
  if (html.includes("canvas") && html.includes("instructure")) {
    return {
      type: "CANVAS",
      baseUrl: new URL(url).origin,
      confidence: 0.8,
    };
  }

  // Check for Kaltura
  if (html.includes("kaltura") || html.includes("kWidget")) {
    return {
      type: "KALTURA",
      baseUrl: new URL(url).origin,
      confidence: 0.8,
    };
  }

  // Check for YouTube embeds
  if (html.includes("youtube.com/embed") || html.includes("youtu.be")) {
    return {
      type: "YOUTUBE",
      baseUrl: new URL(url).origin,
      confidence: 0.7,
    };
  }

  return fromUrl;
}

