/**
 * University Source Discovery Engine — Crawler
 *
 * Crawls university educational platforms to discover courses and resources.
 * Respects robots.txt, rate limits, and platform-specific patterns.
 */

import { db } from "../db.js";
import {
  detectPlatform,
  detectPlatformFromHtml,
  type DetectedPlatform,
  type PlatformType,
} from "./platform-detector.js";

export type CrawlConfig = {
  maxPages: number;
  maxDepth: number;
  delayMs: number; // rate limit delay
  includePatterns: string[];
  excludePatterns: string[];
  userAgent: string;
};

const DEFAULT_CONFIG: CrawlConfig = {
  maxPages: 100,
  maxDepth: 3,
  delayMs: 1000,
  includePatterns: [],
  excludePatterns: ["login", "signup", "register", "apply", "admissions"],
  userAgent: "LearnHigh/1.0 (+https://github.com/learnhigh) University Discovery Bot",
};

type CrawledPage = {
  url: string;
  html: string;
  links: string[];
  depth: number;
};

/**
 * Extract all links from HTML content.
 */
function extractLinks(html: string, baseUrl: string): string[] {
  const links: string[] = [];
  const anchorRegex = /<a[^>]+href=["']([^"']+)["']/gi;
  let match;

  while ((match = anchorRegex.exec(html)) !== null) {
    try {
      const href = match[1];
      // Resolve relative URLs
      const resolved = new URL(href, baseUrl).href;
      // Only keep http/https links
      if (resolved.startsWith("http://") || resolved.startsWith("https://")) {
        links.push(resolved);
      }
    } catch {
      // Skip invalid URLs
    }
  }

  return [...new Set(links)];
}

/**
 * Extract course information from HTML.
 * Looks for common patterns in university course pages.
 */
function extractCourseInfo(
  html: string,
  url: string,
): Array<{
  code: string;
  title: string;
  url: string;
  description?: string;
}> {
  const courses: Array<{
    code: string;
    title: string;
    url: string;
    description?: string;
  }> = [];

  // Pattern 1: Course code in heading followed by title
  // e.g., <h2>CSE 151A - Introduction to Machine Learning</h2>
  const h2Regex =
    /<h[23][^>]*>\s*([A-Z]{2,4}\s+\d{2,4}[A-Za-z]?)\s*[-–—]\s*([^<]+)<\/h[23]>/gi;
  let match;
  while ((match = h2Regex.exec(html)) !== null) {
    courses.push({
      code: match[1].trim(),
      title: match[2].trim(),
      url,
    });
  }

  // Pattern 2: Course links with code in text
  // e.g., <a href="/courses/cse151a">CSE 151A</a>
  const linkRegex =
    /<a[^>]+href=["']([^"']*(?:course|class|lecture)[^"']*)["'][^>]*>\s*([A-Z]{2,4}\s+\d{2,4}[A-Za-z]?)\s*[-–—]?\s*([^<]*)<\/a>/gi;
  while ((match = linkRegex.exec(html)) !== null) {
    const code = match[2].trim();
    const titleFromText = match[3].trim();
    courses.push({
      code,
      title: titleFromText || code,
      url: new URL(match[1], url).href,
    });
  }

  // Pattern 3: Table rows with course data
  // e.g., <tr><td>CSE 151A</td><td>Introduction to Machine Learning</td></tr>
  const tableRegex =
    /<tr[^>]*>\s*<td[^>]*>\s*([A-Z]{2,4}\s+\d{2,4}[A-Za-z]?)\s*<\/td>\s*<td[^>]*>\s*([^<]+)\s*<\/td>/gi;
  while ((match = tableRegex.exec(html)) !== null) {
    courses.push({
      code: match[1].trim(),
      title: match[2].trim(),
      url,
    });
  }

  return courses;
}

/**
 * Extract lecture/video links from a course page.
 */
function extractLectureLinks(html: string, baseUrl: string): string[] {
  const links: string[] = [];
  const allLinks = extractLinks(html, baseUrl);

  for (const link of allLinks) {
    // Video patterns
    if (
      link.includes("/watch") ||
      link.includes("/video") ||
      link.includes("/lecture") ||
      link.includes("youtube.com") ||
      link.includes("youtu.be") ||
      link.includes("podcast") ||
      link.includes("kaltura")
    ) {
      links.push(link);
    }
  }

  return [...new Set(links)];
}

/**
 * Fetch a page with retry logic.
 */
async function fetchPage(
  url: string,
  config: CrawlConfig,
): Promise<{ html: string; ok: boolean }> {
  const maxRetries = 3;
  let lastError: Error | null = null;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const response = await fetch(url, {
        headers: {
          "User-Agent": config.userAgent,
          Accept: "text/html,application/xhtml+xml",
        },
        signal: AbortSignal.timeout(15000),
      });

      if (!response.ok) {
        return { html: "", ok: false };
      }

      const html = await response.text();
      return { html, ok: true };
    } catch (error) {
      lastError = error as Error;
      if (attempt < maxRetries - 1) {
        await new Promise((r) => setTimeout(r, config.delayMs * (attempt + 1)));
      }
    }
  }

  return { html: "", ok: false };
}

/**
 * Check if a URL should be crawled based on config patterns.
 */
function shouldCrawl(url: string, config: CrawlConfig): boolean {
  // Exclude patterns
  for (const pattern of config.excludePatterns) {
    if (url.toLowerCase().includes(pattern.toLowerCase())) {
      return false;
    }
  }

  // Include patterns (if any, URL must match at least one)
  if (config.includePatterns.length > 0) {
    return config.includePatterns.some((p) =>
      url.toLowerCase().includes(p.toLowerCase()),
    );
  }

  return true;
}

/**
 * Crawl a platform starting from its catalog URL.
 */
export async function crawlPlatform(
  platformId: string,
  partialConfig?: Partial<CrawlConfig>,
): Promise<{
  pagesCrawled: number;
  coursesFound: number;
  resourcesFound: number;
  errors: string[];
}> {
  const config = { ...DEFAULT_CONFIG, ...partialConfig };
  const errors: string[] = [];
  const visited = new Set<string>();
  const discoveredCourses: Array<{
    code: string;
    title: string;
    url: string;
  }> = [];
  const discoveredResources: string[] = [];

  // Get platform info
  const platform = await db.universityPlatform.findUnique({
    where: { id: platformId },
    include: { university: true },
  });

  if (!platform) {
    return { pagesCrawled: 0, coursesFound: 0, resourcesFound: 0, errors: ["Platform not found"] };
  }

  // Create crawl job
  const job = await db.crawlJob.create({
    data: {
      platformId,
      status: "RUNNING",
      startedAt: new Date(),
      config: JSON.stringify(config),
    },
  });

  console.log(`🔍 Starting crawl: ${platform.name} (${platform.baseUrl})`);
  console.log(`   Job ID: ${job.id}`);
  console.log(`   Config: maxPages=${config.maxPages}, maxDepth=${config.maxDepth}`);

  // BFS crawl
  const queue: Array<{ url: string; depth: number }> = [];

  // Seed with catalog URL and department URLs
  if (platform.catalogUrl) {
    queue.push({ url: platform.catalogUrl, depth: 0 });
  }
  if (platform.departmentUrl) {
    queue.push({ url: platform.departmentUrl, depth: 0 });
  }
  // Also seed with base URL
  queue.push({ url: platform.baseUrl, depth: 0 });

  let pagesCrawled = 0;

  while (queue.length > 0 && pagesCrawled < config.maxPages) {
    const { url, depth } = queue.shift()!;

    if (visited.has(url) || depth > config.maxDepth) continue;
    if (!shouldCrawl(url, config)) continue;

    visited.add(url);
    pagesCrawled++;

    console.log(`   [${pagesCrawled}/${config.maxPages}] Crawling: ${url}`);

    const { html, ok } = await fetchPage(url, config);

    if (!ok) {
      errors.push(`Failed to fetch: ${url}`);
      continue;
    }

    // Detect platform from HTML
    const detected = detectPlatformFromHtml(url, html);
    if (detected) {
      console.log(`     Platform detected: ${detected.type} (confidence: ${detected.confidence})`);
    }

    // Extract courses from this page
    const courses = extractCourseInfo(html, url);
    for (const course of courses) {
      // Check if we already have this course
      const existing = discoveredCourses.find(
        (c) => c.code === course.code,
      );
      if (!existing) {
        discoveredCourses.push(course);
        console.log(`     📚 Course found: ${course.code} - ${course.title}`);
      }
    }

    // Extract lecture/resource links
    const lectureLinks = extractLectureLinks(html, url);
    discoveredResources.push(...lectureLinks);

    // Extract and queue links for further crawling
    const links = extractLinks(html, url);
    for (const link of links) {
      if (
        !visited.has(link) &&
        shouldCrawl(link, config) &&
        // Stay on the same domain or university subdomains
        isSameUniversityDomain(link, platform.baseUrl)
      ) {
        queue.push({ url: link, depth: depth + 1 });
      }
    }

    // Rate limiting
    await new Promise((r) => setTimeout(r, config.delayMs));
  }

  // Save discovered courses
  for (const course of discoveredCourses) {
    try {
      await db.discoveredCourse.upsert({
        where: {
          platformId_code_term: {
            platformId,
            code: course.code,
            term: null as unknown as string,
          },
        },
        update: {
          title: course.title,
          url: course.url,
        },
        create: {
          platformId,
          code: course.code,
          title: course.title,
          url: course.url,
          status: "DISCOVERED",
        },
      });
    } catch (error) {
      // If term is an issue, try without it
      console.warn(`     ⚠ Failed to save course ${course.code}: ${error}`);
    }
  }

  // Update job status
  const uniqueResources = [...new Set(discoveredResources)];
  await db.crawlJob.update({
    where: { id: job.id },
    data: {
      status: "COMPLETED",
      completedAt: new Date(),
      pagesCrawled,
      coursesFound: discoveredCourses.length,
      resourcesFound: uniqueResources.length,
      errors: errors.length > 0 ? JSON.stringify(errors) : null,
    },
  });

  // Update platform lastCrawledAt
  await db.universityPlatform.update({
    where: { id: platformId },
    data: { lastCrawledAt: new Date() },
  });

  console.log(`\n✅ Crawl complete!`);
  console.log(`   Pages crawled: ${pagesCrawled}`);
  console.log(`   Courses found: ${discoveredCourses.length}`);
  console.log(`   Resources found: ${uniqueResources.length}`);
  console.log(`   Errors: ${errors.length}`);

  return {
    pagesCrawled,
    coursesFound: discoveredCourses.length,
    resourcesFound: uniqueResources.length,
    errors,
  };
}

/**
 * Check if two URLs are from the same university domain.
 */
function isSameUniversityDomain(url1: string, url2: string): boolean {
  try {
    const u1 = new URL(url1);
    const u2 = new URL(url2);

    // Same base domain
    const domain1 = u1.hostname.split(".").slice(-2).join(".");
    const domain2 = u2.hostname.split(".").slice(-2).join(".");

    return domain1 === domain2;
  } catch {
    return false;
  }
}

/**
 * Quick scan a single URL for courses (no deep crawl).
 */
export async function scanUrl(
  url: string,
): Promise<{
  platform: DetectedPlatform | null;
  courses: Array<{ code: string; title: string; url: string }>;
  resources: string[];
}> {
  const { html, ok } = await fetchPage(url, {
    ...DEFAULT_CONFIG,
    maxPages: 1,
    maxDepth: 0,
  });

  if (!ok) {
    return { platform: null, courses: [], resources: [] };
  }

  const platform = detectPlatformFromHtml(url, html);
  const courses = extractCourseInfo(html, url);
  const resources = extractLectureLinks(html, url);

  return {
    platform,
    courses,
    resources: [...new Set(resources)],
  };
}

/**
 * University Source Discovery Engine — Normalizer
 *
 * Maps discovered courses and resources to the existing data model.
 * Handles deduplication, skill matching, and quality scoring.
 */

import { db } from "../db.js";

export type NormalizationResult = {
  coursesCreated: number;
  coursesUpdated: number;
  resourcesCreated: number;
  resourcesLinked: number;
  skillsLinked: number;
  errors: string[];
};

/**
 * Normalize a discovered course into the Course + Resource models.
 */
export async function normalizeDiscoveredCourse(
  discoveredCourseId: string,
): Promise<NormalizationResult> {
  const result: NormalizationResult = {
    coursesCreated: 0,
    coursesUpdated: 0,
    resourcesCreated: 0,
    resourcesLinked: 0,
    skillsLinked: 0,
    errors: [],
  };

  const discovered = await db.discoveredCourse.findUnique({
    where: { id: discoveredCourseId },
    include: {
      platform: {
        include: { university: true },
      },
      resources: true,
    },
  });

  if (!discovered) {
    result.errors.push(`Discovered course not found: ${discoveredCourseId}`);
    return result;
  }

  const university = discovered.platform.university;

  // Create or update the Course
  const courseSlug = `${university.slug}-${discovered.code.toLowerCase().replace(/\s+/g, "-")}`;

  const course = await db.course.upsert({
    where: { slug: courseSlug },
    update: {
      title: discovered.title,
      description: discovered.description,
      code: discovered.code,
      url: discovered.url,
      universityId: university.id,
    },
    create: {
      slug: courseSlug,
      code: discovered.code,
      title: discovered.title,
      description: discovered.description,
      url: discovered.url,
      universityId: university.id,
      level: guessLevel(discovered.code),
    },
  });

  if (course.createdAt.getTime() === course.updatedAt.getTime()) {
    result.coursesCreated++;
  } else {
    result.coursesUpdated++;
  }

  // Create Resource for the course itself
  const resourceSlug = `${courseSlug}-course`;
  const year = extractYear(discovered.term);

  const courseResource = await db.resource.upsert({
    where: { slug: resourceSlug },
    update: {
      title: `${discovered.code} - ${discovered.title}`,
      description: discovered.description,
      instructor: discovered.instructor,
      url: discovered.url,
      year,
      universityId: university.id,
      courseId: course.id,
    },
    create: {
      slug: resourceSlug,
      title: `${discovered.code} - ${discovered.title}`,
      type: "COURSE",
      url: discovered.url,
      description: discovered.description,
      instructor: discovered.instructor,
      language: "en",
      level: guessLevel(discovered.code),
      year,
      universityId: university.id,
      courseId: course.id,
      qualityScore: 70, // base score, will be improved
      verified: false,
    },
  });

  result.resourcesCreated++;

  // Normalize discovered resources (lectures, notes, etc.)
  for (const discoveredResource of discovered.resources) {
    try {
      const resourceType = guessResourceType(discoveredResource.url);
      const resourceSlug = `${courseSlug}-${resourceType.toLowerCase()}-${hashUrl(discoveredResource.url)}`;

      const resource = await db.resource.upsert({
        where: { slug: resourceSlug },
        update: {
          url: discoveredResource.url,
        },
        create: {
          slug: resourceSlug,
          title: `${discovered.code} - ${resourceType}`,
          type: resourceType,
          url: discoveredResource.url,
          language: "en",
          level: guessLevel(discovered.code),
          year,
          universityId: university.id,
          courseId: course.id,
          qualityScore: 60,
          verified: false,
        },
      });

      result.resourcesCreated++;

      // Link resource to course if not already linked
      await db.resourceSkill.createMany({
        data: [], // Will be linked when skills are matched
        skipDuplicates: true,
      });
    } catch (error) {
      result.errors.push(
        `Failed to normalize resource ${discoveredResource.url}: ${error}`,
      );
    }
  }

  // Try to match skills based on course code and title
  const matchedSkills = await matchSkills(discovered.code, discovered.title);
  for (const skill of matchedSkills) {
    try {
      await db.resourceSkill.upsert({
        where: {
          resourceId_skillId: {
            resourceId: courseResource.id,
            skillId: skill.id,
          },
        },
        update: { isPrimary: true },
        create: {
          resourceId: courseResource.id,
          skillId: skill.id,
          isPrimary: true,
        },
      });
      result.skillsLinked++;
    } catch (error) {
      result.errors.push(
        `Failed to link skill ${skill.slug} to resource: ${error}`,
      );
    }
  }

  // Mark as imported
  await db.discoveredCourse.update({
    where: { id: discoveredCourseId },
    data: { status: "IMPORTED" },
  });

  return result;
}

/**
 * Normalize all discovered courses for a platform.
 */
export async function normalizePlatform(
  platformId: string,
): Promise<NormalizationResult> {
  const result: NormalizationResult = {
    coursesCreated: 0,
    coursesUpdated: 0,
    resourcesCreated: 0,
    resourcesLinked: 0,
    skillsLinked: 0,
    errors: [],
  };

  const courses = await db.discoveredCourse.findMany({
    where: { platformId, status: "DISCOVERED" },
  });

  console.log(`\n🔄 Normalizing ${courses.length} discovered courses...`);

  for (const course of courses) {
    console.log(`   Processing: ${course.code} - ${course.title}`);
    const courseResult = await normalizeDiscoveredCourse(course.id);

    result.coursesCreated += courseResult.coursesCreated;
    result.coursesUpdated += courseResult.coursesUpdated;
    result.resourcesCreated += courseResult.resourcesCreated;
    result.resourcesLinked += courseResult.resourcesLinked;
    result.skillsLinked += courseResult.skillsLinked;
    result.errors.push(...courseResult.errors);
  }

  console.log(`\n✅ Normalization complete!`);
  console.log(`   Courses created: ${result.coursesCreated}`);
  console.log(`   Courses updated: ${result.coursesUpdated}`);
  console.log(`   Resources created: ${result.resourcesCreated}`);
  console.log(`   Skills linked: ${result.skillsLinked}`);

  return result;
}

/**
 * Match a course to existing skills based on code and title.
 */
async function matchSkills(
  code: string,
  title: string,
): Promise<Array<{ id: string; slug: string; name: string }>> {
  const normalizedCode = code.toUpperCase().replace(/\s+/g, "");
  const normalizedTitle = title.toLowerCase();

  // Keyword-based matching
  const keywords = extractKeywords(normalizedTitle);

  const skills = await db.skill.findMany({
    where: {
      OR: [
        { slug: { in: keywords.map((k) => k.toLowerCase()) } },
        { name: { contains: keywords[0] ?? "" } },
      ],
    },
    select: { id: true, slug: true, name: true },
    take: 5,
  });

  return skills;
}

/**
 * Extract meaningful keywords from a course title.
 */
function extractKeywords(title: string): string[] {
  const stopWords = new Set([
    "introduction",
    "to",
    "and",
    "or",
    "the",
    "of",
    "in",
    "for",
    "a",
    "an",
    "on",
    "with",
    "from",
    "by",
    "at",
    "this",
    "that",
    "course",
    "basic",
    "advanced",
    "intermediate",
    "principles",
    "concepts",
  ]);

  return title
    .split(/[\s,.\-_/]+/)
    .filter((w) => w.length > 2 && !stopWords.has(w))
    .slice(0, 5);
}

/**
 * Guess the level from course code.
 */
function guessLevel(code: string): string {
  const numbers = code.match(/\d+/);
  if (!numbers) return "INTERMEDIATE";

  const num = parseInt(numbers[0], 10);
  if (num < 100) return "BEGINNER";
  if (num < 200) return "INTERMEDIATE";
  return "ADVANCED";
}

/**
 * Guess resource type from URL.
 */
function guessResourceType(url: string): string {
  const lower = url.toLowerCase();

  if (lower.includes("youtube") || lower.includes("video") || lower.includes("watch")) {
    return "LECTURE";
  }
  if (lower.includes("pdf") || lower.includes("notes") || lower.includes("slides")) {
    return "LECTURE_NOTES";
  }
  if (lower.includes("assignment") || lower.includes("homework") || lower.includes("hw")) {
    return "EXERCISE";
  }
  if (lower.includes("exam") || lower.includes("midterm") || lower.includes("final")) {
    return "EXAM";
  }
  if (lower.includes("syllabus")) {
    return "SYLLABUS";
  }
  if (lower.includes("book") || lower.includes("textbook") || lower.includes("reading")) {
    return "BOOK";
  }

  return "LECTURE";
}

/**
 * Extract year from term string.
 */
function extractYear(term: string | null): number | null {
  if (!term) return null;

  // Match patterns like "wi24", "sp23", "f2023", "2024"
  const yearMatch = term.match(/(\d{2,4})$/);
  if (yearMatch) {
    let year = parseInt(yearMatch[1], 10);
    if (year < 100) year += 2000;
    if (year >= 2000 && year <= 2030) return year;
  }

  return null;
}

/**
 * Simple hash for URL to create unique slugs.
 */
function hashUrl(url: string): string {
  let hash = 0;
  for (let i = 0; i < url.length; i++) {
    const char = url.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0;
  }
  return Math.abs(hash).toString(36);
}

