import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { handle } from "@/lib/http";
import { crawlPlatform } from "@/lib/discovery/crawler";

/**
 * POST /api/discovery/crawl
 * Start a crawl job for a platform.
 */
export async function POST(request: Request) {
  return handle(async () => {
    const body = await request.json();
    const { platformId, maxPages, maxDepth, delayMs } = body;

    if (!platformId) {
      return NextResponse.json(
        { error: "Missing required field: platformId" },
        { status: 400 },
      );
    }

    const platform = await db.universityPlatform.findUnique({
      where: { id: platformId },
      include: { university: true },
    });

    if (!platform) {
      return NextResponse.json(
        { error: `Platform not found: ${platformId}` },
        { status: 404 },
      );
    }

    // Check if there's already a running job
    const runningJob = await db.crawlJob.findFirst({
      where: {
        platformId,
        status: "RUNNING",
      },
    });

    if (runningJob) {
      return NextResponse.json(
        { error: "A crawl job is already running for this platform", jobId: runningJob.id },
        { status: 409 },
      );
    }

    // Start crawl in background (non-blocking)
    const config = {
      maxPages: maxPages ?? 50,
      maxDepth: maxDepth ?? 3,
      delayMs: delayMs ?? 1000,
    };

    // Run crawl asynchronously
    crawlPlatform(platformId, config).catch((error) => {
      console.error(`Crawl failed for ${platform.name}:`, error);
    });

    return NextResponse.json({
      data: {
        message: `Crawl started for ${platform.name}`,
        platform: platform.name,
        config,
      },
    });
  });
}

