    return NextResponse.json({ data: jobs });
  });
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { handle } from "@/lib/http";
import { normalizePlatform } from "@/lib/discovery/normalizer";

/**
 * POST /api/discovery/normalize
 * Normalize discovered courses for a platform into the main data model.
 */
export async function POST(request: Request) {
  return handle(async () => {
    const body = await request.json();
    const { platformId } = body;

    if (!platformId) {
      return NextResponse.json(
        { error: "Missing required field: platformId" },
        { status: 400 },
      );
    }

    const platform = await db.universityPlatform.findUnique({
      where: { id: platformId },
      include: { university: true },
    });

    if (!platform) {
      return NextResponse.json(
        { error: `Platform not found: ${platformId}` },
        { status: 404 },
      );
    }

    // Count discovered courses
    const discoveredCount = await db.discoveredCourse.count({
      where: { platformId, status: "DISCOVERED" },
    });

    if (discoveredCount === 0) {
      return NextResponse.json(
        { error: "No discovered courses to normalize. Run a crawl first." },
        { status: 400 },
      );
    }

    // Run normalization
    const result = await normalizePlatform(platformId);

    return NextResponse.json({
      data: {
        platform: platform.name,
        university: platform.university.name,
        ...result,
      },
    });
  });
}

/**
 * GET /api/discovery/normalize
 * List discovered courses pending normalization.
 */
export async function GET() {
  return handle(async () => {
    const courses = await db.discoveredCourse.findMany({
      include: {
        platform: {
          include: { university: true },
        },
        _count: { select: { resources: true } },
      },
      where: { status: "DISCOVERED" },
      orderBy: { createdAt: "desc" },
      take: 50,
    });

    const stats = await db.discoveredCourse.groupBy({
      by: ["status"],
      _count: true,
    });

    return NextResponse.json({
      data: {
        courses,
        stats: stats.reduce(
          (acc, s) => ({ ...acc, [s.status]: s._count }),
          {} as Record<string, number>,
        ),
      },
    });
  });
}

import { NextResponse } from "next/server";
import { handle } from "@/lib/http";
import { scanUrl } from "@/lib/discovery/crawler";

/**
 * POST /api/discovery/scan
 * Quick scan a URL to detect platform type and find courses.
 */
export async function POST(request: Request) {
  return handle(async () => {
    const body = await request.json();
    const { url } = body;

    if (!url) {
      return NextResponse.json(
        { error: "Missing required field: url" },
        { status: 400 },
      );
    }

    try {
      new URL(url);
    } catch {
      return NextResponse.json(
        { error: "Invalid URL format" },
        { status: 400 },
      );
    }

    const result = await scanUrl(url);

    return NextResponse.json({
      data: {
        url,
        platform: result.platform,
        coursesFound: result.courses.length,
        courses: result.courses,
        resourcesFound: result.resources.length,
        resources: result.resources.slice(0, 20), // Limit output
      },
    });
  });
}

"use client";

import { useState, useEffect } from "react";

type Platform = {
  id: string;
  name: string;
  baseUrl: string;
  type: string;
  university: { name: string; slug: string };
  lastCrawledAt: string | null;
  _count: { discovered: number; jobs: number };
};

type CrawlJob = {
  id: string;
  status: string;
  pagesCrawled: number;
  coursesFound: number;
  resourcesFound: number;
  startedAt: string | null;
  completedAt: string | null;
  platform: { name: string; university: { name: string } };
};

type ScanResult = {
  url: string;
  platform: { type: string; baseUrl: string; confidence: number } | null;
  coursesFound: number;
  courses: Array<{ code: string; title: string; url: string }>;
  resourcesFound: number;
};

export default function DiscoveryPage() {
  const [platforms, setPlatforms] = useState<Platform[]>([]);
  const [jobs, setJobs] = useState<CrawlJob[]>([]);
  const [scanUrl, setScanUrl] = useState("");
  const [scanResult, setScanResult] = useState<ScanResult | null>(null);
  const [scanning, setScanning] = useState(false);
  const [crawling, setCrawling] = useState<string | null>(null);

  useEffect(() => {
    fetchPlatforms();
    fetchJobs();
  }, []);

  const fetchPlatforms = async () => {
    const res = await fetch("/api/discovery/platforms");
    const data = await res.json();
    setPlatforms(data.data);
  };

  const fetchJobs = async () => {
    const res = await fetch("/api/discovery/crawl");
    const data = await res.json();
    setJobs(data.data);
  };

  const handleScan = async () => {
    if (!scanUrl) return;
    setScanning(true);
    setScanResult(null);

    try {
      const res = await fetch("/api/discovery/scan", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: scanUrl }),
      });
      const data = await res.json();
      setScanResult(data.data);
    } catch (error) {
      console.error("Scan failed:", error);
    } finally {
      setScanning(false);
    }
  };

  const handleCrawl = async (platformId: string) => {
    setCrawling(platformId);

    try {
      await fetch("/api/discovery/crawl", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ platformId, maxPages: 30, maxDepth: 2 }),
      });
      // Refresh jobs after a delay
      setTimeout(fetchJobs, 2000);
    } catch (error) {
      console.error("Crawl failed:", error);
    } finally {
      setCrawling(null);
    }
  };

  return (
    <div className="mx-auto max-w-6xl px-4 py-12">
      <div className="mb-8">
        <h1 className="font-display text-3xl font-bold text-fg">
          University Source Discovery Engine
        </h1>
        <p className="mt-2 text-fg-muted">
          Discover and normalize educational resources from university platforms.
        </p>
      </div>

      {/* URL Scanner */}
      <section className="mb-8 rounded-xl border border-border bg-card p-6">
        <h2 className="mb-4 font-display text-xl font-semibold text-fg">
          Quick Scan
        </h2>
        <p className="mb-4 text-sm text-fg-muted">
          Paste a university URL to detect its platform type and discover courses.
        </p>
        <div className="flex gap-3">
          <input
            type="url"
            value={scanUrl}
            onChange={(e) => setScanUrl(e.target.value)}
            placeholder="https://podcast.ucsd.edu or https://ocw.mit.edu/courses/"
            className="flex-1 rounded-lg border border-border bg-bg px-4 py-2 text-fg placeholder:text-fg-faint focus:border-accent focus:outline-none"
          />
          <button
            onClick={handleScan}
            disabled={scanning || !scanUrl}
            className="rounded-lg bg-accent px-6 py-2 font-medium text-card transition-colors hover:bg-accent-dark disabled:opacity-50"
          >
            {scanning ? "Scanning..." : "Scan"}
          </button>
        </div>

        {scanResult && (
          <div className="mt-4 rounded-lg border border-border bg-bg p-4">
            <div className="grid gap-4 sm:grid-cols-3">
              <div>
                <span className="text-xs text-fg-faint">Platform Type</span>
                <p className="font-medium text-fg">
                  {scanResult.platform?.type ?? "Unknown"}
                </p>
              </div>
              <div>
                <span className="text-xs text-fg-faint">Courses Found</span>
                <p className="font-medium text-fg">{scanResult.coursesFound}</p>
              </div>
              <div>
                <span className="text-xs text-fg-faint">Resources Found</span>
                <p className="font-medium text-fg">{scanResult.resourcesFound}</p>
              </div>
            </div>
            {scanResult.courses.length > 0 && (
              <div className="mt-4">
                <h3 className="mb-2 text-sm font-semibold text-fg">Discovered Courses:</h3>
                <ul className="space-y-1">
                  {scanResult.courses.map((c, i) => (
                    <li key={i} className="text-sm text-fg-muted">
                      <span className="font-medium text-fg">{c.code}</span> - {c.title}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}
      </section>

      {/* Platforms */}
      <section className="mb-8">
        <h2 className="mb-4 font-display text-xl font-semibold text-fg">
          Registered Platforms
        </h2>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {platforms.map((p) => (
            <div
              key={p.id}
              className="rounded-xl border border-border bg-card p-4"
            >
              <div className="flex items-start justify-between">
                <div>
                  <h3 className="font-semibold text-fg">{p.name}</h3>
                  <p className="text-sm text-fg-muted">{p.university.name}</p>
                  <p className="mt-1 text-xs text-fg-faint">{p.baseUrl}</p>
                </div>
                <span className="rounded-full bg-muted px-2 py-0.5 text-xs font-medium text-fg-muted">
                  {p.type}
                </span>
              </div>
              <div className="mt-3 flex items-center justify-between text-xs text-fg-faint">
                <span>{p._count.discovered} discovered</span>
                <span>{p._count.jobs} jobs</span>
              </div>
              {p.lastCrawledAt && (
                <p className="mt-1 text-xs text-fg-faint">
                  Last crawled: {new Date(p.lastCrawledAt).toLocaleDateString()}
                </p>
              )}
              <button
                onClick={() => handleCrawl(p.id)}
                disabled={crawling === p.id}
                className="mt-3 w-full rounded-lg border border-border px-3 py-1.5 text-sm font-medium text-fg transition-colors hover:border-accent hover:text-accent disabled:opacity-50"
              >
                {crawling === p.id ? "Crawling..." : "Start Crawl"}
              </button>
            </div>
          ))}
        </div>
      </section>

      {/* Recent Jobs */}
      <section>
        <h2 className="mb-4 font-display text-xl font-semibold text-fg">
          Recent Crawl Jobs
        </h2>
        {jobs.length === 0 ? (
          <p className="text-fg-muted">No crawl jobs yet.</p>
        ) : (
          <div className="space-y-3">
            {jobs.map((job) => (
              <div
                key={job.id}
                className="flex items-center justify-between rounded-lg border border-border bg-card p-4"
              >
                <div>
                  <p className="font-medium text-fg">
                    {job.platform.university.name} - {job.platform.name}
                  </p>
                  <p className="text-sm text-fg-muted">
                    {job.pagesCrawled} pages · {job.coursesFound} courses ·{" "}
                    {job.resourcesFound} resources
                  </p>
                </div>
                <span
                  className={`rounded-full px-3 py-1 text-xs font-medium ${
                    job.status === "COMPLETED"
                      ? "bg-success-light text-success"
                      : job.status === "RUNNING"
                        ? "bg-accent-light text-accent-dark"
                        : job.status === "FAILED"
                          ? "bg-error-light text-error"
                          : "bg-muted text-fg-muted"
                  }`}
                >
                  {job.status}
                </span>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

