/**
 * POST /api/discovery/platforms
 * Register a new university platform.
 */
export async function POST(request: Request) {
  return handle(async () => {
    const body = await request.json();
    const { universitySlug, name, baseUrl, type, departmentUrl, catalogUrl } = body;

    if (!universitySlug || !name || !baseUrl || !type) {
      return NextResponse.json(
        { error: "Missing required fields: universitySlug, name, baseUrl, type" },
        { status: 400 },
      );
    }

    const university = await db.university.findUnique({
      where: { slug: universitySlug },
    });

    if (!university) {
      return NextResponse.json(
        { error: `University not found: ${universitySlug}` },
        { status: 404 },
      );
    }

    const slug = name.toLowerCase().replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "");

    const platform = await db.universityPlatform.upsert({
      where: { slug },
      update: {
        name,
        baseUrl,
        type,
        departmentUrl,
        catalogUrl,
      },
      create: {
        slug,
        universityId: university.id,
        name,
        baseUrl,
        type,
        departmentUrl,
        catalogUrl,
      },
    });

    return NextResponse.json({ data: platform });
  });
}

