input.content:
/**
 * University Course Catalog Seed
 *
 * Builds the curated course database:
 *   Course (+ CoursePrerequisite graph)
 *   Degree → Curriculum → CurriculumCourse (official parcours)
 *   LearningPath derived from the curriculum
 *   Resource ↔ Course linkage (library built on top of the parcours)
 */

import path from "node:path";
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import { PrismaClient } from "../../src/generated/prisma/client.js";
import {
  ucsdCseCatalog,
  ucsdBsCsCurriculum,
} from "./data/ucsd-cse-catalog.js";

const dbPath = path.resolve(process.cwd(), "prisma/dev.db");
const adapter = new PrismaBetterSqlite3({ url: `file:${dbPath}` });
const prisma = new PrismaClient({ adapter });

const UNIVERSITY_SLUG = "ucsd";
const DEGREE_SLUG = "ucsd-bs-computer-science";
const PATH_SLUG = "ucsd-bs-computer-science";

function courseSlug(universitySlug: string, code: string): string {
  return `${universitySlug}-${code.toLowerCase().replace(/\s+/g, "-")}`;
}

async function seedCourses() {
  console.log("📚 Seeding curated course catalog (UCSD CSE)...");

  const university = await prisma.university.findUnique({
    where: { slug: UNIVERSITY_SLUG },
  });
  if (!university) throw new Error(`University ${UNIVERSITY_SLUG} not found. Run base seed first.`);

  const globalSkills = await prisma.skill.findMany({
    select: { id: true, slug: true },
  });
  const skillBySlug = new Map(globalSkills.map((s) => [s.slug, s]));

  let coursesCreated = 0;
  let coursesUpdated = 0;
  const courseIdByCode = new Map<string, string>();
  const unknownSkills = new Set<string>();

  for (const c of ucsdCseCatalog) {
    const slug = courseSlug(UNIVERSITY_SLUG, c.code);
    const level =
      c.catalogLevel === "LOWER_DIVISION"
        ? "BEGINNER"
        : c.code.startsWith("CSE 1") && parseInt(c.code.split(" ")[1], 10) >= 120
          ? "ADVANCED"
          : "INTERMEDIATE";

    const existing = await prisma.course.findUnique({ where: { slug } });

    const course = await prisma.course.upsert({
      where: { slug },
      update: {
        code: c.code,
        title: c.title,
        description: c.description,
        catalogLevel: c.catalogLevel,
        units: c.units,
        url: c.catalogUrl,
        level,
        universityId: university.id,
      },
      create: {
        slug,
        code: c.code,
        title: c.title,
        description: c.description,
        catalogLevel: c.catalogLevel,
        units: c.units,
        url: c.catalogUrl,
        level,
        universityId: university.id,
      },
    });

    if (existing) coursesUpdated++;
    else coursesCreated++;
    courseIdByCode.set(c.code, course.id);

    // Link course to skills
    for (const skillSlug of c.skillSlugs) {
      const skill = skillBySlug.get(skillSlug);
      if (!skill) {
        unknownSkills.add(skillSlug);
        continue;
      }
      // Reuse ResourceSkill join? No — course↔skill is expressed through resources.
      // Skills are linked via the resources attached to this course.
      void skill;
    }
  }

  // Second pass: prerequisites
  let prereqCreated = 0;
  let prereqMissing = 0;
  for (const c of ucsdCseCatalog) {
    const courseId = courseIdByCode.get(c.code)!;
    for (const prereqCode of c.prerequisites) {
      const prereqId = courseIdByCode.get(prereqCode);
      if (!prereqId) {
        console.warn(`  ⚠ Prerequisite ${prereqCode} of ${c.code} not in catalog`);
        prereqMissing++;
        continue;
      }
      const existing = await prisma.coursePrerequisite.findUnique({
        where: { courseId_prerequisiteId: { courseId, prerequisiteId: prereqId } },
      });
      if (!existing) {
        await prisma.coursePrerequisite.create({
          data: { courseId, prerequisiteId: prereqId },
        });
        prereqCreated++;
      }
    }
  }

  console.log(`  ✓ Courses: ${coursesCreated} created, ${coursesUpdated} updated`);
  console.log(`  ✓ Prerequisites: ${prereqCreated} created, ${prereqMissing} missing`);
  if (unknownSkills.size > 0) {
    console.warn(`  ⚠ Unknown skill slugs (skipped): ${[...unknownSkills].join(", ")}`);
  }
}

async function seedCurriculum() {
  console.log("\n🎓 Seeding curriculum (UCSD BS Computer Science)...");

  const university = await prisma.university.findUnique({
    where: { slug: UNIVERSITY_SLUG },
  });
  if (!university) throw new Error("University not found");

  // Degree
  const degree = await prisma.degree.upsert({
    where: { slug: DEGREE_SLUG },
    update: { name: "BS Computer Science", universityId: university.id },
    create: {
      slug: DEGREE_SLUG,
      name: "BS Computer Science",
      level: "BACHELOR",
      universityId: university.id,
    },
  });

  // Curriculum
  let curriculum = await prisma.curriculum.findFirst({
    where: { degreeId: degree.id },
  });
  if (!curriculum) {
    curriculum = await prisma.curriculum.create({
      data: {
        degreeId: degree.id,
        name: "CSE BS 2022–23",
        source: "https://catalog.ucsd.edu/archive/2022-23/curric/CSE-ug.html",
      },
    });
  }

  // CurriculumCourse entries
  let entries = 0;
  for (const q of ucsdBsCsCurriculum) {
    for (const code of q.courseCodes) {
      const courseSlugKey = courseSlug(UNIVERSITY_SLUG, code);
      const course = await prisma.course.findUnique({ where: { slug: courseSlugKey } });
      if (!course) {
        console.warn(`  ⚠ Course ${code} not found for curriculum`);
        continue;
      }
      const order = (q.year - 1) * 10 + (q.quarter === "FALL" ? 0 : q.quarter === "WINTER" ? 1 : 2);
      await prisma.curriculumCourse.upsert({
        where: { curriculumId_courseId: { curriculumId: curriculum.id, courseId: course.id } },
        update: { year: q.year, semester: order },
        create: {
          curriculumId: curriculum.id,
          courseId: course.id,
          year: q.year,
          semester: order,
          order,
        },
      });
      entries++;
    }
  }
  console.log(`  ✓ Degree + curriculum created, ${entries} course entries`);
}

async function seedLearningPath() {
  console.log("\n🛤  Generating learning path from curriculum...");

  const domain = await prisma.domain.findUnique({ where: { slug: "computer-science" } });
  if (!domain) throw new Error("Domain computer-science not found. Run base seed first.");

  const globalSkills = await prisma.skill.findMany({ select: { id: true, slug: true } });
  const skillBySlug = new Map(globalSkills.map((s) => [s.slug, s]));

  const path = await prisma.learningPath.upsert({
    where: { slug: PATH_SLUG },
    update: {
      name: "UCSD BS Computer Science",
      tagline: "Parcours officiel du Bachelor of Science en Computer Science de UCSD",
      domainId: domain.id,
      estimatedMonths: 48,
    },
    create: {
      slug: PATH_SLUG,
      domainId: domain.id,
      name: "UCSD BS Computer Science",
      tagline: "Parcours officiel du Bachelor of Science en Computer Science de UCSD",
      description:
        "Learning path fidèle au curriculum officiel UCSD CSE (2022–23) : programmation, structures de données, algorithmes, théorie, systèmes, IA/ML. Les phases correspondent aux années du cursus.",
      level: "BEGINNER",
      estimatedMonths: 48,
      order: 100,
    },
  });

  // Build ordered steps: curriculum order, skills from each course
  const seenSkills = new Set<string>();
  let order = 0;
  let stepsCreated = 0;
  let stepsSkipped = 0;

  for (const q of ucsdBsCsCurriculum) {
    for (const code of q.courseCodes) {
      const catalogEntry = ucsdCseCatalog.find((c) => c.code === code);
      if (!catalogEntry) continue;

      for (const skillSlug of catalogEntry.skillSlugs) {
        if (seenSkills.has(skillSlug)) {
          stepsSkipped++;
          continue;
        }
        const skill = skillBySlug.get(skillSlug);
        if (!skill) {
          stepsSkipped++;
          continue;
        }
        seenSkills.add(skillSlug);

        await prisma.learningPathStep.upsert({
          where: { pathId_skillId: { pathId: path.id, skillId: skill.id } },
          update: { phase: `YEAR ${q.year}`, order, isRequired: true },
          create: {
            pathId: path.id,
            skillId: skill.id,
            phase: `YEAR ${q.year}`,
            order,
            isRequired: true,
          },
        });
        order++;
        stepsCreated++;
      }
    }
  }

  console.log(`  ✓ Path "${path.name}": ${stepsCreated} steps (4 phases YEAR 1→4), ${stepsSkipped} dedup/skipped`);
}

async function linkResourcesToCourses() {
  console.log("\n🔗 Linking existing resources to courses...");

  const university = await prisma.university.findUnique({
    where: { slug: UNIVERSITY_SLUG },
  });
  if (!university) throw new Error("University not found");

  const resources = await prisma.resource.findMany({
    where: { universityId: university.id },
    select: { id: true, slug: true, courseId: true },
  });

  let linked = 0;
  for (const c of ucsdCseCatalog) {
    const courseId = await prisma.course.findUnique({
      where: { slug: courseSlug(UNIVERSITY_SLUG, c.code) },
      select: { id: true },
    });
    if (!courseId) continue;

    const prefix = courseSlug(UNIVERSITY_SLUG, c.code);
    for (const r of resources) {
      if (r.slug.startsWith(prefix)) {
        if (r.courseId !== courseId.id) {
          await prisma.resource.update({
            where: { id: r.id },
            data: { courseId: courseId.id },
          });
          linked++;
        }
      }
    }
  }

  console.log(`  ✓ ${linked} resources linked to their course`);
}

async function printStats() {
  const [courses, prereqs, curriculumEntries, pathSteps] = await Promise.all([
    prisma.course.count({ where: { universityId: { not: null } } }),
    prisma.coursePrerequisite.count(),
    prisma.curriculumCourse.count(),
    prisma.learningPathStep.count({ where: { path: { slug: PATH_SLUG } } }),
  ]);

  console.log("\n📊 Catalog stats:");
  console.log(`  Courses: ${courses}`);
  console.log(`  Course prerequisites: ${prereqs}`);
  console.log(`  Curriculum entries: ${curriculumEntries}`);
  console.log(`  Learning path steps (UCSD BS CS): ${pathSteps}`);
}

seedCourses()
  .then(() => seedCurriculum())
  .then(() => seedLearningPath())
  .then(() => linkResourcesToCourses())
  .then(() => printStats())
  .then(async () => {
    await prisma.$disconnect();
    console.log("\n🎉 Catalog seed complete!");
  })
  .catch(async (e) => {
    console.error(e);
    await prisma.$disconnect();
    process.exit(1);
  });

import { db } from "@/lib/db";
import { handle, json, error } from "@/lib/http";

/**
 * GET /api/courses?university=ucsd&level=UPPER_DIVISION
 * List courses, optionally filtered by university slug.
 */
export const GET = handle(async (request: Request) => {
  const { searchParams } = new URL(request.url);
  const universitySlug = searchParams.get("university");
  const catalogLevel = searchParams.get("level");

  const where = {
    ...(universitySlug ? { university: { slug: universitySlug } } : {}),
    ...(catalogLevel ? { catalogLevel } : {}),
  };

  const courses = await db.course.findMany({
    where,
    include: {
      university: { select: { name: true, slug: true } },
      _count: {
        select: { prerequisites: true, unlocks: true, resources: true },
      },
    },
    orderBy: [{ university: { name: "asc" } }, { code: "asc" }],
  });

  return json(courses);
});

import { db } from "@/lib/db";
import { handle, json, error } from "@/lib/http";

/**
 * GET /api/courses/[slug]
 * Course detail: prerequisites, unlocks, resources, curriculum placement.
 */
export const GET = handle(
  async (_request: Request, context?: Record<string, unknown>) => {
    const { slug } = context as { slug: string };

    const course = await db.course.findUnique({
      where: { slug },
      include: {
        university: { select: { name: true, slug: true, country: true } },
        prerequisites: {
          include: {
            prerequisite: { select: { slug: true, code: true, title: true, units: true } },
          },
        },
        unlocks: {
          include: {
            course: { select: { slug: true, code: true, title: true, units: true } },
          },
        },
        resources: {
          select: {
            slug: true,
            title: true,
            type: true,
            url: true,
            year: true,
            qualityScore: true,
            verified: true,
            instructor: true,
          },
        },
        entries: {
          include: {
            curriculum: {
              select: {
                name: true,
                degree: {
                  select: { name: true, slug: true, university: { select: { name: true } } },
                },
              },
            },
          },
        },
      },
    });

    if (!course) return error(404, "Course not found");
    return json(course);
  },
);

