import Link from "next/link";
import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { getPathProgress, computeStreak } from "@/lib/skills";
import { db } from "@/lib/db";
import { ProgressBar } from "@/components/ProgressBar";
import { SkillStatusBadge } from "@/components/SkillStatusBadge";
import { DailyMission } from "@/components/DailyMission";
import { ContinueLearning } from "@/components/ContinueLearning";

export default async function DashboardPage() {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const [activeGoal, streak, recentProgress, allBookmarks] = await Promise.all([
    db.userGoal.findFirst({
      where: { userId: user.id, status: "ACTIVE" },
      include: {
        path: {
          include: {
            domain: { select: { name: true, slug: true } },
          },
        },
      },
    }),
    computeStreak(user.id),
    db.userProgress.findMany({
      where: { userId: user.id },
      include: { resource: { select: { slug: true, title: true, type: true } } },
      orderBy: { lastAccessedAt: "desc" },
      take: 5,
    }),
    db.bookmark.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 5,
    }),
  ]);

  let progress = null;
  if (activeGoal) {
    progress = await getPathProgress(user.id, activeGoal.path.slug);
  }

  return (
    <div className="mx-auto max-w-6xl px-4 py-12">
      <div className="mb-8">
        <h1 className="font-display text-3xl font-bold text-fg">
          Welcome back{user.name ? `, ${user.name}` : ""}
