import { DailyMission } from "@/components/DailyMission";
import { ContinueLearning } from "@/components/ContinueLearning";
import { UniversityPicker } from "@/components/UniversityPicker";

export default async function DashboardPage() {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const [userData, activeGoal, streak, recentProgress, allBookmarks] = await Promise.all([
    db.user.findUnique({
      where: { id: user.id },
      select: {
        university: {
          select: {
            slug: true,
            name: true,
            country: true,
            _count: { select: { courses: true, resources: true } },
          },
        },
      },
    }),
    db.userGoal.findFirst({
      where: { userId: user.id, status: "ACTIVE" },
      include: {
        path: {
          include: {
            domain: { select: { name: true, slug: true } },
          },
        },
      },
    }),
    computeStreak(user.id),
    db.userProgress.findMany({
      where: { userId: user.id },
      include: { resource: { select: { slug: true, title: true, type: true } } },
      orderBy: { lastAccessedAt: "desc" },
      take: 5,
    }),
    db.bookmark.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 5,
    }),
  ]);

  const university = userData?.university ?? null;

  // University curriculum paths (paths whose slug starts with the university slug)
  const uniPaths = university
    ? await db.learningPath.findMany({
        where: { slug: { startsWith: `${university.slug}-` } },
        include: { domain: { select: { name: true, slug: true } }, _count: { select: { steps: true } } },
        take: 4,
      })
    : [];

  let progress = null;
  if (activeGoal) {
    progress = await getPathProgress(user.id, activeGoal.path.slug);
  }

  return (
    <div className="mx-auto max-w-6xl px-4 py-12">
      <div className="mb-8">
        <h1 className="font-display text-3xl font-bold text-fg">
          Welcome back{user.name ? `, ${user.name}` : ""}
        </h1>
        {streak > 0 && (
          <p className="mt-2 text-fg-muted">
            🔥 {streak} day streak
          </p>
        )}
      </div>

      {/* University onboarding */}
      {!university && (
        <div className="mb-8">
          <UniversityPicker currentSlug={null} />
        </div>
      )}

      {/* Daily Mission — prominent */}
      <div className="mb-8">
        <DailyMission />
      </div>

