  // Exact heading match — "1. Core Courses" — prose mentions are ignored
  const start = body.findIndex((l) => /^(\d+\.\s*)?Core Courses$/i.test(l.trim()));
  if (start === -1) return [];
  const end = body.findIndex(
    (l, i) => i > start && /^(\d+\.\s*)?Electives\b/i.test(l.trim()),
  );
