```

Structure:
- `prisma/seed/catalog.ts`:
  - export cleanInvalidCatalog(db)
  - import { importUcsdDepartment } from import-ucsd-dept.ts
  - seedUcsdResources()
  - main: clean → import CSE → resources → stats

Refactor import-ucsd-dept.ts: wrap logic in `export async function importUcsdDepartment(dept, year)` and only auto-run if invoked directly (check process.argv[1] includes import-ucsd-dept).

Clean logic:
```ts
async function cleanInvalidCatalog() {
  // 1. unlink resources from invalid courses
  const invalidCourses = await prisma.course.findMany({ where: { slug: { not: { startsWith: "ucsd-cse-" } } }, select: { id: true } });
  // resources linked to invalid courses → unlink (courseId null)
  await prisma.resource.updateMany({ where: { courseId: { in: invalidCourseIds } }, data: { courseId: null } });
  // 2. delete curriculum entries for invalid courses
  await prisma.curriculumCourse.deleteMany({ where: { courseId: { in: ids } } });
  // 3. delete prereq edges
  await prisma.coursePrerequisite.deleteMany({ where: { OR: [{ courseId: { in: ids } }, { prerequisiteId: { in: ids } }] } });
  // 4. delete courses
  await prisma.course.deleteMany({ where: { id: { in: ids } } });
  // 5. delete non-UCSD university resources + their ResourceSkill
  const nonUcsd = await prisma.resource.findMany({ where: { university: { slug: { not: "ucsd" } } }, select: { id: true } });
  await prisma.resourceSkill.deleteMany({ where: { resourceId: { in: nonUcsdIds } } });
  await prisma.resource.deleteMany({ where: { id: { in: nonUcsdIds } } });
}
