display.text:
import Link from "next/link";
import { db } from "@/lib/db";
import { notFound } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { getPathProgress } from "@/lib/skills";
import { SkillStatusBadge } from "@/components/SkillStatusBadge";
import { ProgressBar } from "@/components/ProgressBar";
import { SetGoalButton } from "@/components/SetGoalButton";

export default async function PathDetailPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const user = await getCurrentUser();

  const path = await db.learningPath.findUnique({
    where: { slug },
    include: {
      domain: { select: { name: true, slug: true } },
      steps: {
        include: {
          skill: {
            include: {
              resources: {
                include: { resource: { select: { slug: true, title: true, university: { select: { name: true } } } } },
                where: { isPrimary: true },
                take: 1,
              },
              prerequisites: { select: { prerequisite: { select: { slug: true, name: true } } } },
            },
          },
        },
        orderBy: { order: "asc" },
      },
      userGoals: user ? { where: { userId: user.id }, select: { id: true } } : false,
    },
  });

  if (!path) notFound();

  // Compute progress if user is logged in
  let progress = null;
  if (user) {
    progress = await getPathProgress(user.id, slug);
  }

  // Group steps by phase
  const phases = new Map<string, typeof path.steps>();
  for (const step of path.steps) {
    const existing = phases.get(step.phase) || [];
    existing.push(step);
    phases.set(step.phase, existing);
  }

  const hasGoal = path.userGoals && path.userGoals.length > 0;

  return (
    <div className="mx-auto max-w-4xl px-4 py-12">
      <div className="mb-8">
        <div className="flex items-center gap-2 text-sm text-fg-muted">
          <Link href="/domains" className="hover:text-fg">Domains</Link>
          <span>/</span>
          <Link href={`/domains/${path.domain.slug}`} className="hover:text-fg">{path.domain.name}</Link>
          <span>/</span>
          <span className="text-fg">{path.name}</span>
        </div>

        <h1 className="mt-3 font-display text-3xl font-bold text-fg">{path.name}</h1>
        <p className="mt-2 text-lg text-fg-muted">{path.tagline}</p>

        <div className="mt-4 flex items-center gap-4 text-sm text-fg-faint">
          {path.estimatedMonths && <span>{path.estimatedMonths} months estimated</span>}
          <span>{path.steps.length} skills</span>
          {path.level && (
            <span className="rounded-full bg-muted px-2.5 py-0.5 text-xs">{path.level}</span>
          )}
        </div>

        {!user && (
          <div className="mt-6 rounded-lg border border-accent/30 bg-accent-light/50 p-4">
            <p className="text-sm text-accent-dark">
              <Link href="/login" className="font-medium underline">Log in</Link> to track your progress and set this as your goal.
            </p>
          </div>
        )}

        {user && !hasGoal && (
          <div className="mt-6">
            <SetGoalButton pathSlug={slug} />
          </div>
        )}
      </div>

      {/* Progress */}
      {progress && (
        <div className="mb-8 rounded-lg border border-border bg-card p-6">
          <div className="flex items-center justify-between">
            <h2 className="font-display text-lg font-semibold text-fg">Your Progress</h2>
            <span className="text-2xl font-bold text-accent">{progress.percentage}%</span>
          </div>
          <ProgressBar value={progress.percentage} className="mt-3" />
          <div className="mt-3 flex items-center gap-4 text-sm text-fg-muted">
            <span>{progress.completedSteps} / {progress.totalSteps} skills completed</span>
            {progress.currentPhase && (
              <span>Current phase: <span className="font-medium text-fg">{progress.currentPhase}</span></span>
            )}
          </div>
          {progress.nextTask && (
            <div className="mt-4 rounded-md bg-muted p-3">
              <span className="text-xs font-medium text-fg-faint">NEXT UP</span>
              <p className="mt-0.5 text-sm font-medium text-fg">{progress.nextTask.skillName}</p>
              {progress.nextTask.resourceUrl && (
                <a
                  href={progress.nextTask.resourceUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="mt-1 inline-block text-xs text-accent hover:text-accent-dark"
                >
                  Open resource &rarr;
                </a>
              )}
            </div>
          )}
        </div>
      )}

      {/* Phases */}
      <div className="space-y-8">
        {Array.from(phases.entries()).map(([phase, steps], phaseIdx) => (
          <div key={phase} className="relative">
            <div className="sticky top-[var(--nav-height)] z-10 flex items-center gap-3 bg-background py-3">
              <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-fg text-sm font-bold text-card">
                {phaseIdx + 1}
              </span>
              <h2 className="font-display text-xl font-semibold text-fg">{phase}</h2>
            </div>

            <div className="ml-4 space-y-3 border-l-2 border-border pl-8">
              {steps.map((step) => {
                const userSkill = progress?.statuses.find((s) => s.slug === step.skill.slug);
                const status = userSkill?.status ?? "AVAILABLE";
                const primaryResource = step.skill.resources[0]?.resource;

                return (
                  <div key={step.id} className="relative">
                    {/* Connector dot */}
                    <div className={`absolute -left-[33px] top-3 h-3 w-3 rounded-full border-2 border-background ${
                      status === "COMPLETED" || status === "MASTERED"
                        ? "bg-completed"
                        : status === "IN_PROGRESS"
                        ? "bg-in-progress"
                        : status === "LOCKED"
                        ? "bg-locked"
                        : "bg-available"
                    }`} />

                    <Link
                      href={`/skills/${step.skill.slug}`}
                      className={`block rounded-lg border bg-card p-4 transition-all ${
                        status === "LOCKED"
                          ? "border-border opacity-60"
                          : "border-border hover:border-accent/40 hover:shadow-sm"
                      }`}
                    >
                      <div className="flex items-start justify-between gap-4">
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2">
                            <h3 className="font-medium text-fg">{step.skill.name}</h3>
                            <SkillStatusBadge status={status} />
                          </div>
                          {step.skill.description && (
                            <p className="mt-1 line-clamp-2 text-sm text-fg-muted">
                              {step.skill.description}
                            </p>
                          )}
                          {primaryResource && (
                            <p className="mt-2 text-xs text-fg-faint">
                              {primaryResource.university?.name} — {primaryResource.title}
                            </p>
                          )}
                        </div>
                        {userSkill && userSkill.mastery > 0 && (
                          <span className="shrink-0 text-sm font-semibold text-accent">
                            {Math.round(userSkill.mastery)}%
                          </span>
                        )}
                      </div>

                      {/* Prerequisites shown for locked skills */}
                      {status === "LOCKED" && step.skill.prerequisites.length > 0 && (
                        <div className="mt-2 text-xs text-fg-faint">
                          Requires: {step.skill.prerequisites.map((p) => p.prerequisite.name).join(", ")}
                        </div>
                      )}
                    </Link>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

