input.content:
import Link from "next/link";
import { db } from "@/lib/db";
import { notFound } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { getPathProgress } from "@/lib/skills";
import { SkillStatusBadge } from "@/components/SkillStatusBadge";
import { ProgressBar } from "@/components/ProgressBar";
import { SetGoalButton } from "@/components/SetGoalButton";

type StepStatus = "LOCKED" | "AVAILABLE" | "IN_PROGRESS" | "COMPLETED" | "MASTERED";

const DOT_COLOR: Record<StepStatus, string> = {
  COMPLETED: "bg-completed",
  MASTERED: "bg-completed",
  IN_PROGRESS: "bg-in-progress",
  LOCKED: "bg-locked",
  AVAILABLE: "bg-available",
};

type CourseStep = NonNullable<
  Awaited<ReturnType<typeof loadPath>>["steps"][number]["course"]
>;
type SkillStep = NonNullable<
  Awaited<ReturnType<typeof loadPath>>["steps"][number]["skill"]
>;

async function loadPath(slug: string) {
  return db.learningPath.findUnique({
    where: { slug },
    include: {
      domain: { select: { name: true, slug: true } },
      steps: {
        include: {
          skill: {
            include: {
              resources: {
                include: { resource: { select: { slug: true, title: true, university: { select: { name: true } } } } },
                where: { isPrimary: true },
                take: 1,
              },
              prerequisites: { select: { prerequisite: { select: { slug: true, name: true } } } },
            },
          },
          course: {
            include: {
              prerequisites: {
                include: { prerequisite: { select: { slug: true, code: true, title: true } } },
              },
              unlocks: { include: { course: { select: { code: true } } } },
              _count: { select: { resources: true } },
            },
          },
        },
        orderBy: { order: "asc" },
      },
      userGoals: true,
    },
  });
}

export default async function PathDetailPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const user = await getCurrentUser();

  const path = await loadPath(slug);
  if (!path) notFound();

  const progress = user ? await getPathProgress(user.id, slug) : null;

  // ── Build hierarchical blocks: numbered sequence + condensed choice groups ──
  type Block =
    | { kind: "course"; n: number; course: CourseStep; isRequired: boolean }
    | { kind: "skill"; n: number; skill: SkillStep }
    | { kind: "choice"; n: number; courses: CourseStep[] };

  const phases = new Map<string, Block[]>();
  let n = 0;

  for (const step of path.steps) {
    const blocks = phases.get(step.phase) ?? [];

    if (step.course) {
      const course = step.course;
      if (!step.isRequired) {
        // Extend or start a choice group
        const last = blocks[blocks.length - 1];
        if (last && last.kind === "choice") {
          last.courses.push(course);
        } else {
          n++;
          blocks.push({ kind: "choice", n, courses: [course] });
        }
      } else {
        n++;
        blocks.push({ kind: "course", n, course, isRequired: true });
      }
    } else if (step.skill) {
      n++;
      blocks.push({ kind: "skill", n, skill: step.skill });
    }

    phases.set(step.phase, blocks);
  }

  const hasGoal = path.userGoals.length > 0;
  const nextTaskSlug = progress?.nextTask?.slug ?? null;

  return (
    <div className="mx-auto max-w-4xl px-4 py-12">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center gap-2 text-sm text-fg-muted">
          <Link hrefう="/domains" className="hover:text-fg">Domains</Link>
          <span>/</span>
          <Link href={`/domains/${path.domain.slug}`} className="hover:text-fg">{path.domain.name}</Link>
          <span>/</span>
          <span className="text-fg">{path.name}</span>
        </div>

        <h1 className="mt-3 font-display text-3xl font-bold text-fg">{path.name}</h1>
        <p className="mt-2 text-lg text-fg-muted">{path.tagline}</p>

        <div className="mt-4 flex flex-wrap items-center gap-4 text-sm text-fg-faint">
          {path.estimatedMonths && <span>{path.estimatedMonths} months estimated</span>}
          <span>{phases.size} phases</span>
          <span>{path.steps.filter((s) => s.courseId).length} courses</span>
          {path.level && (
            <span className="rounded-full bg-muted px-2.5 py-0.5 text-xs">{path.level}</span>
          )}
        </div>

        {!user && (
          <div className="mt-6 rounded-lg border border-accent/30 bg-accent-light/50 p-4">
            <p className="text-sm text-accent-dark">
              <Link href="/login" className="font-medium underline">Log in</Link> to track your progress and set this as your goal.
            </p>
          </div>
        )}

        {user && !hasGoal && (
          <div className="mt-6">
            <SetGoalButton pathSlug={slug} />
          </div>
        )}
      </div>

      {/* Progress */}
      {progress && (
        <div className="mb-8 rounded-lg border border-border bg-card p-6">
          <div className="flex items-center justify-between">
            <h2 className="font-display text-lg font-semibold text-fg">Your Progress</h2>
            <span className="text-2xl font-bold text-accent">{progress.percentage}%</span>
          </div>
          <ProgressBar value={progress.percentage} className="mt-3" />
          <div className="mt-3 flex items-center gap-4 text-sm text-fg-muted">
            <span>{progress.completedSteps} / {progress.totalSteps} steps completed</span>
            {progress.currentPhase && (
              <span>Current phase: <span className="font-medium text-fg">{progress.currentPhase}</span></span>
            )}
          </div>
          {progress.nextTask && (
            <div className="mt-4 rounded-md bg-muted p-3">
              <span className="text-xs font-medium text-fg-faint">
                NEXT UP — {progress.nextTask.kind === "COURSE" ? "COURSE" : "SKILL"}
              </span>
              <p className="mt-0.5 text-sm font-medium text-fg">{progress.nextTask.name}</p>
              <div className="mt-1 flex items-center gap-3">
                <Link href={progress.nextTask.href} className="text-xs text-accent hover:text-accent-dark">
                  Open &rarr;
                </Link>
                {progress.nextTask.resourceUrl && (
                  <a
                    href={progress.nextTask.resourceUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-xs text-fg-muted hover:text-fg"
                  >
                    Start learning &rarr;
                  </a>
                )}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Roadmap overview — the hierarchy at a glance */}
      <div className="mb-10 rounded-xl border border-border bg-card p-5">
        <h2 className="mb-3 font-display text-sm font-semibold uppercase tracking-wide text-fg-faint">
          Roadmap
        </h2>
        <div className="flex flex-wrap items-center gap-2">
          {[...phases.keys()].map((phase, i) => (
            <span key={phase} className="flex items-center gap-2">
              {i > 0 && <span className="text-fg-faint">→</span>}
              <span className="flex items-center gap-1.5 rounded-full bg-muted px-3 py-1 text-xs font-medium text-fg">
                <span className="flex h-4.5 w-4.5 items-center justify-center rounded-full bg-fg text-[10px] font-bold text-card">
                  {i + 1}
                </span>
                {phase}
              </span>
            </span>
          ))}
        </div>
      </div>

      {/* Phases with hierarchical blocks */}
      <div className="space-y-10">
        {[...phases.entries()].map(([phase, blocks], phaseIdx) => {
          const done = blocks.filter((b) => {
            if (b.kind === "course") {
              return progress?.courseStatuses.find((c) => c.slug === b.course.slug)?.status === "COMPLETED";
            }
            if (b.kind === "skill") {
              const st = progress?.statuses.find((s) => s.slug === b.skill.slug);
              return st?.status === "COMPLETED" || st?.status === "MASTERED";
            }
            return b.courses.some(
              (c) => progress?.courseStatuses.find((cs) => cs.slug === c.slug)?.status === "COMPLETED",
            );
          }).length;

          return (
            <div key={phase}>
              {/* Phase header */}
              <div className="sticky top-14 lg:top-0 z-10 flex items-center gap-3 bg-background py-3">
                <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-fg text-base font-bold text-card">
                  {phaseIdx + 1}
                </span>
                <div className="min-w-0 flex-1">
                  <h2 className="font-display text-xl font-semibold text-fg">{phase}</h2>
                </div>
                <span className="shrink-0 text-xs font-medium text-fg-faint">
                  {done}/{blocks.length} done
                </span>
              </div>

              {/* Sequence */}
              <div className="ml-4 space-y-3 border-l-2 border-border pl-6">
                {blocks.map((block) => {
                  /* ── Required course ── */
                  if (block.kind === "course") {
                    const st = progress?.courseStatuses.find((c) => c.slug === block.course.slug);
                    const status: StepStatus = st?.status ?? "AVAILABLE";
                    const isNext = nextTaskSlug === block.course.slug;

                    return (
                      <div key={block.course.slug} className="relative">
                        <div className={`absolute -left-[31px] top-4 flex h-3.5 w-3.5 items-center justify-center rounded-full border-2 border-background ${DOT_COLOR[status]}`} />
                        <CourseCard
                          course={block.course}
                          number={block.n}
                          status={status}
                          percent={st?.percent ?? 0}
                          prereqDone={block.course.prerequisites.map((p) => ({
                            code: p.prerequisite.code,
                            title: p.prerequisite.title,
                            done:
                              progress?.courseStatuses.find(
                                (c) => c.code === p.prerequisite.code,
                              )?.status === "COMPLETED",
                          }))}
                          unlocks={block.course.unlocks.map((u) => u.course.code).filter(Boolean).slice(0, 4)}
                          isNext={isNext}
                        />
                      </div>
                    );
                  }

                  /* ── Choice group ── */
                  if (block.kind === "choice") {
                    const groupDone = block.courses.some(
                      (c) => progress?.courseStatuses.find((cs) => cs.slug === c.slug)?.status === "COMPLETED",
                    );
                    return (
                      <div key={`choice-${block.n}`} className="relative">
                        <div className={`absolute -left-[31px] top-4 h-3.5 w-3.5 rounded-full border-2 border-background ${groupDone ? "bg-completed" : "bg-available"}`} />
                        <div className={`rounded-lg border p-4 transition-all ${
                          groupDone ? "border-completed/40 bg-card" : "border-dashed border-accent/40 bg-accent-light/20"
                        }`}>
                          <div className="flex flex-wrap items-center gap-2">
                            <span className="flex h-6 w-6 items-center justify-center rounded-full bg-muted font-mono text-xs font-bold text-fg-muted">
                              {block.n}
                            </span>
                            <span className="text-xs font-bold uppercase tracking-wide text-accent-dark">
                              AU CHOIX
                            </span>
                            <span className="text-xs text-fg-faint">
                              — choisissez {block.courses.length > 1 ? "1 parmi" : ""} :
                            </span>
                            {groupDone && (
                              <span className="rounded bg-completed/15 px-2 py-0.5 text-xs font-medium text-completed">
                                validé ✓
                              </span>
                            )}
                          </div>
                          <div className="mt-3 grid gap-2 sm:grid-cols-2">
                            {block.courses.map((c) => {
                              const cst = progress?.courseStatuses.find((cs) => cs.slug === c.slug);
                              return (
                                <Link
                                  key={c.slug}
                                  href={`/courses/${c.slug}`}
                                  className={`flex items-center justify-between gap-2 rounded-md border px-3 py-2 text-sm transition-colors hover:border-accent/50 ${
