// Phase 1 — Lower division. Entry/2-unit choice courses come FIRST (they are
// the prerequisites of the required sequence), sorted by catalog number.
const lower = program.lowerDivisionCodes.filter((c) => courseIdByCode.has(c));
const lowerAlternatives = new Set([
  "CSE 3", "CSE 4GS", "CSE 6R", "CSE 6GS", "CSE 8A", "CSE 8B", "CSE 11",
  "CSE 42", "CSE 86", "CSE 90", "CSE 91", "CSE 95", "CSE 99", "CSE 180", "CSE 180R",
]);
const byNumber = (a: string, b: string) => {
  const na = parseInt(a.replace(/\D+/g, ""), 10) || 0;
  const nb = parseInt(b.replace(/\D+/g, ""), 10) || 0;
  return na - nb || a.localeCompare(b);
};
const lowerOrdered = [
  ...lower.filter((c) => lowerAlternatives.has(c)).sort(byNumber),
  ...lower.filter((c) => !lowerAlternatives.has(c)),
];
for (const code of lowerOrdered) {
  await addCourseStep("LOWER DIVISION", code, !lowerAlternatives.has(code));
