input.content:
import { db } from "./db";

/**
 * Dynamic weekly schedule.
 *
 * The student enrolls in N courses in parallel (they cohabit, like a real
 * quarter). Each enrollment anchors the course's official week structure
 * (Week 1..10 from the podcast platform) to the student's own start date:
 * "week 1" is their first week, whatever the calendar says.
 */

const MS_WEEK = 7 * 24 * 60 * 60 * 1000;

export type ScheduleSessionView = {
  resourceSlug: string;
  title: string;
  url: string;
  sessionKind: string;
  lectureNumber: number;
  dateLabel: string | null;
  status: string;
  percent: number;
};

export type ScheduleCourseView = {
  courseSlug: string;
  code: string;
  title: string;
  term: string | null;
  enrollmentId: string;
  startDate: Date;
  currentWeek: number;
  maxWeek: number;
  weekStart: Date;
  weekEnd: Date;
  sessions: ScheduleSessionView[];
  weekDone: number;
  weekTotal: number;
  overallDone: number;
  overallTotal: number;
};

export type ScheduleView = {
  today: Date;
  courses: ScheduleCourseView[];
};

export async function enroll(
  userId: string,
  courseSlug: string,
  startDate?: Date,
): Promise<void> {
  const course = await db.course.findUnique({
    where: { slug: courseSlug },
    select: { id: true },
  });
  if (!course) throw new Error(`Course not found: ${courseSlug}`);

  await db.scheduleEnrollment.upsert({
    where: { userId_courseId: { userId, courseId: course.id } },
    update: { startDate: startDate ?? new Date(), status: "ACTIVE" },
    create: {
      userId,
      courseId: course.id,
      startDate: startDate ?? new Date(),
      status: "ACTIVE",
    },
  });
}

export async function unenroll(userId: string, courseSlug: string): Promise<void> {
  const course = await db.course.findUnique({
    where: { slug: courseSlug },
    select: { id: true },
  });
  if (!course) return;
  await db.scheduleEnrollment.deleteMany({
    where: { userId, courseId: course.id },
  });
}

function currentWeekOf(startDate: Date, maxWeek: number, now: Date): number {
  if (maxWeek <= 0) return 1;
  const elapsed = Math.floor((now.getTime() - startDate.getTime()) / MS_WEEK) + 1;
  return Math.min(Math.max(elapsed, 1), maxWeek);
}

export async function getScheduleView(userId: string): Promise<ScheduleView> {
  const now = new Date();

  const enrollments = await db.scheduleEnrollment.findMany({
    where: { userId, status: "ACTIVE" },
    include: {
      course: {
        include: {
          resources: {
            where: { weekNumber: { not: null } },
            orderBy: [{ weekNumber: "asc" }, { lectureNumber: "asc" }],
            select: {
              id: true,
              slug: true,
              title: true,
              url: true,
              type: true,
              term: true,
              weekNumber: true,
              lectureNumber: true,
              sessionKind: true,
              dateLabel: true,
              progress: {
                where: { userId },
                select: { status: true, percent: true },
              },
            },
          },
        },
      },
    },
  });

  const courses: ScheduleCourseView[] = [];

  for (const enrollment of enrollments) {
    const { course } = enrollment;
    const byWeek = new Map<number, typeof course.resources>();
    for (const r of course.resources) {
      const w = r.weekNumber!;
      const arr = byWeek.get(w) ?? [];
      arr.push(r);
      byWeek.set(w, arr);
    }
    const maxWeek = Math.max(0, ...byWeek.keys());
    if (maxWeek === 0) continue;

    const currentWeek = currentWeekOf(enrollment.startDate, maxWeek, now);
    const weekStart = new Date(enrollment.startDate.getTime() + (currentWeek - 1) * MS_WEEK);
    const weekEnd = new Date(weekStart.getTime() + MS_WEEK - 1);

    const weekResources = byWeek.get(currentWeek) ?? [];
    const allProgress = course.resources.flatMap((r) =>
      r.progress.length > 0 ? [r.progress[0]] : [],
    );

    const toSession = (r: (typeof course.resources)[number]): ScheduleSessionView => ({
      resourceSlug: r.slug,
      title: r.title,
      url: r.url,
      sessionKind: r.sessionKind ?? "LECTURE",
      lectureNumber: r.lectureNumber ?? 0,
      dateLabel: r.dateLabel,
      status: r.progress[0]?.status ?? "NOT_STARTED",
      percent: r.progress[0]?.percent ?? 0,
    });

    courses.push({
      courseSlug: course.slug,
      code: course.code ?? course.slug,
      title: course.title,
      term: course.resources[0]?.term ?? null,
      enrollmentId: enrollment.id,
      startDate: enrollment.startDate,
      currentWeek,
      maxWeek,
      weekStart,
      weekEnd,
      sessions: weekResources.map(toSession),
      weekDone: weekResources.filter((r) => r.progress[0]?.status === "COMPLETED").length,
      weekTotal: weekResources.length,
      overallDone: allProgress.filter((p) => p.status === "COMPLETED").length,
      overallTotal: course.resources.length,
    });
  }

  courses.sort((a, b) => a.code.localeCompare(b.code));
  return { today: now, courses };
}

import { z } from "zod";
import { requireUser } from "@/lib/auth";
import { handle, json, badRequest } from "@/lib/http";
import { enroll, unenroll, getScheduleView } from "@/lib/schedule";

/**
 * GET /api/schedule — the user's weekly schedule view (all enrolled courses).
 */
export const GET = handle(async () => {
  const user = await requireUser();
  const view = await getScheduleView(user.id);
  return json(view);
});

const enrollSchema = z.object({
  courseSlug: z.string().min(1),
  startDate: z.string().datetime().optional(),
});

/**
 * POST /api/schedule — enroll a course in the personal weekly schedule.
 */
export const POST = handle(async (request: Request) => {
  const user = await requireUser();
  const parsed = enrollSchema.safeParse(await request.json());
  if (!parsed.success) return badRequest("Invalid input");

  await enroll(
    user.id,
    parsed.data.courseSlug,
    parsed.data.startDate ? new Date(parsed.data.startDate) : undefined,
  );
  return json({ enrolled: parsed.data.courseSlug });
});

/**
 * DELETE /api/schedule?courseSlug= — leave the schedule for a course.
 */
export const DELETE = handle(async (request: Request) => {
  const user = await requireUser();
  const courseSlug = new URL(request.url).searchParams.get("courseSlug");
  if (!courseSlug) return badRequest("Missing 'courseSlug' parameter");

  await unenroll(user.id, courseSlug);
  return json({ left: courseSlug });
});

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

export function LectureCheck({
  resourceSlug,
  done,
}: {
  resourceSlug: string;
  done: boolean;
}) {
  const router = useRouter();
  const [checked, setChecked] = useState(done);
  const [busy, setBusy] = useState(false);

  const toggle = async () => {
    setBusy(true);
    const next = !checked;
    try {
      await fetch("/api/progress", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          resourceSlug,
          status: next ? "COMPLETED" : "NOT_STARTED",
        }),
      });
      setChecked(next);
      router.refresh();
    } finally {
      setBusy(false);
    }
  };

  return (
    <button
      onClick={toggle}
      disabled={busy}
      aria-label={checked ? "Marquer comme à faire" : "Marquer comme fait"}
      className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-sm border-2 transition-colors ${
        checked
          ? "border-completed bg-completed text-white"
          : "border-border-strong bg-card hover:border-accent"
      }`}
    >
      {checked && (
        <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
        </svg>
      )}
    </button>
  );
}

export function EnrollButton({
  courseSlug,
  enrolled,
}: {
  courseSlug: string;
  enrolled: boolean;
}) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [active, setActive] = useState(enrolled);

  const toggle = async () => {
    setBusy(true);
    try {
      if (active) {
        await fetch(`/api/schedule?courseSlug=${courseSlug}`, { method: "DELETE" });
        setActive(false);
      } else {
        await fetch("/api/schedule", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ courseSlug }),
        });
        setActive(true);
      }
      router.refresh();
    } finally {
      setBusy(false);
    }
  };

  return (
    <button
      onClick={toggle}
      disabled={busy}
      className={`rounded-sm px-4 py-2 text-sm font-medium transition-colors disabled:opacity-50 ${
        active
          ? "border border-border text-fg-muted hover:border-accent hover:text-accent"
          : "bg-accent text-white hover:bg-accent-dark"
      }`}
    >
      {active ? "Quitter l'emploi du temps" : "Suivre cet emploi du temps"}
    </button>
  );
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { getScheduleView } from "@/lib/schedule";
import { LectureCheck } from "@/components/ScheduleControls";

function fmtDate(d: Date): string {
  return d.toLocaleDateString("fr-FR", { day: "numeric", month: "short" });
}

export default async function SchedulePage() {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const view = await getScheduleView(user.id);

  return (
    <div className="mx-auto max-w-5xl px-4 py-12">
      <header className="mb-10">
        <p className="data-label">Emploi du temps</p>
        <h1 className="mt-1 font-display text-3xl font-bold text-fg">Ta semaine</h1>
        <p className="mt-2 text-fg-muted">
          Chaque cours suit sa structure officielle (semaines 1→10 du département), calée
          sur ta date de début. Coche ce que tu as regardé.
        </p>
      </header>

      {view.courses.length === 0 ? (
        <div className="border-l-4 border-border bg-card p-6">
          <h2 className="font-display text-xl font-semibold text-fg">
            Aucun cours dans ton emploi du temps
          </h2>
          <p className="mt-2 text-sm text-fg-muted">
            Ouvre un cours du catalogue et clique « Suivre cet emploi du temps » — la
            semaine 1 commence à ta date de départ, pas à celle de l&apos;université.
          </p>
          <Link
            href="/courses"
            className="mt-4 inline-block rounded-sm bg-accent px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-accent-dark"
          >
            Voir le catalogue
          </Link>
        </div>
      ) : (
        <div className="space-y-8">
          {view.courses.map((c) => {
            const allDone = c.weekTotal > 0 && c.weekDone === c.weekTotal;
            return (
              <section key={c.courseSlug} className="border border-border bg-card">
                {/* Course header */}
                <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-3">
                  <div className="flex items-baseline gap-3">
                    <span className="course-code text-accent">{c.code}</span>
                    <Link href={`/courses/${c.courseSlug}`} className="font-medium text-fg hover:text-accent">
                      {c.title}
                    </Link>
                    {c.term && <span className="font-mono text-xs text-fg-faint">{c.term}</span>}
                  </div>
                  <span className="font-mono text-xs text-fg-muted">
                    semaine {c.currentWeek}/{c.maxWeek} · {fmtDate(c.weekStart)} →{" "}
                    {fmtDate(c.weekEnd)} · {c.weekDone}/{c.weekTotal}
                  </span>
                </div>

                {/* Week progress strip */}
                <div className="px-5 pt-3">
                  <div className="progress-bar">
                    <div
                      className="progress-bar-fill"
                      style={{ width: c.weekTotal ? (c.weekDone / c.weekTotal) * 100 : 0 }}
                    />
                  </div>
                  <p className="mt-1.5 font-mono text-xs text-fg-faint">
                    cursus complet : {c.overallDone}/{c.overallTotal} sessions
                  </p>
                </div>

                {/* Sessions */}
                <ul className="divide-y divide-border px-5 py-2">
                  {c.sessions.map((s) => (
                    <li key={s.resourceSlug} className="flex items-center gap-3 py-2.5">
                      <LectureCheck resourceSlug={s.resourceSlug} done={s.status === "COMPLETED"} />
                      <a
                        href={s.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="min-w-0 flex-1"
                      >
                        <span className="block truncate text-sm text-fg hover:text-accent">
                          {s.title}
                        </span>
                      </a>
                      <span className="shrink-0 font-mono text-xs text-fg-faint">
                        {s.sessionKind === "DISCUSSION" ? "disc." : `lect. ${s.lectureNumber}`}
                      </span>
                      {s.dateLabel && (
                        <span className="hidden shrink-0 font-mono text-xs text-fg-faint sm:block">
                          {s.dateLabel}
                        </span>
                      )}
                    </li>
                  ))}
                  {c.sessions.length === 0 && (
                    <li className="py-3 text-sm text-fg-muted">
                      Semaine {c.currentWeek} — aucune session cette semaine
                      {allDone ? " (tout est fait ✓)" : ""}.
                    </li>
                  )}
                </ul>
              </section>
            );
          })}
        </div>
      )}
    </div>
  );
}

